// Project-mode generation/import should only expose tools that actually write
// hooks into the workspace. This keeps global-only targets out of project
// target lists while still allowing them in global mode.
const hooksProcessorToolTargets: ToolTarget[] = [...toolHooksFactories.entries()]
  .filter(([, f]) => f.meta.supportsProject)
  .map(([t]) => t);
const hooksProcessorToolTargetsGlobal: ToolTarget[] = [...toolHooksFactories.entries()]
  .filter(([, f]) => f.meta.supportsGlobal)
  .map(([t]) => t);
const hooksProcessorToolTargetsImportable: ToolTarget[] = [...toolHooksFactories.entries()]
  .filter(([, f]) => f.meta.supportsProject && f.meta.supportsImport)
  .map(([t]) => t);
const hooksProcessorToolTargetsGlobalImportable: ToolTarget[] = [...toolHooksFactories.entries()]
  .filter(([, f]) => f.meta.supportsGlobal && f.meta.supportsImport)
  .map(([t]) => t);

export class HooksProcessor extends FeatureProcessor {
  private readonly toolTarget: HooksProcessorToolTarget;
  private readonly global: boolean;
  private readonly preserveUnownedHooks: boolean;

  constructor({
    outputRoot = process.cwd(),
    inputRoots,
    toolTarget,
    global = false,
    dryRun = false,
    preserveUnownedHooks = false,
    logger,
  }: {
    outputRoot?: string;
    inputRoots?: readonly [string, ...string[]] | readonly string[];
    toolTarget: ToolTarget;
    global?: boolean;
    dryRun?: boolean;
    preserveUnownedHooks?: boolean;
    logger: Logger;
  }) {
    super({ outputRoot, inputRoots, dryRun, logger });
    const result = HooksProcessorToolTargetSchema.safeParse(toolTarget);
    if (!result.success) {
      throw new Error(
        `Invalid tool target for HooksProcessor: ${toolTarget}. ${formatError(result.error)}`,
      );
    }
    this.toolTarget = result.data;
    this.global = global;
    this.preserveUnownedHooks = preserveUnownedHooks;
  }

  async loadRulesyncFiles(): Promise<RulesyncFile[]> {
    // `inputRoots[i]` is a source tree itself (e.g. `/repo/.rulesync.local`);
    // hooks files live directly inside it (no implicit `.rulesync/` prefix).
    //
    // Multi-root policy: the last root that provides a hooks file wins the
    // whole file (see the inputRoots plan). Recommended and legacy paths are
    // treated equally per-root — either one qualifies as "root has hooks".
    const paths = RulesyncHooks.getSettablePaths();
    const relativePaths = getRulesyncSourceCandidates({ paths }).map(
      (candidate) => candidate.relativeFilePath,
    );
    try {
      const winningRoot = await pickLastRootWithFile({
        inputRoots: this.inputRoots,
        relativePaths,
        logger: this.logger,
        artifactName: "The hooks file",
      });
      const sourceTree = winningRoot ?? this.inputRoots[0];

      return [
        await RulesyncHooks.fromFile({
          outputRoot: dirname(sourceTree),
          relativeDirPath: basename(sourceTree),
          validate: true,
        }),
      ];
    } catch (error) {
      this.reportRulesyncSourceLoadError({
        message: `Failed to load Rulesync hooks file (${RULESYNC_HOOKS_RELATIVE_FILE_PATH})`,
        error,
      });
      return [];
    }
  }

  async loadToolFiles({
    forDeletion = false,
  }: {
    forDeletion?: boolean;
  } = {}): Promise<ToolFile[]> {
    try {
      const factory = toolHooksFactories.get(this.toolTarget);
      if (!factory) throw new Error(`Unsupported tool target: ${this.toolTarget}`);
      const paths = factory.class.getSettablePaths({ global: this.global });

      if (forDeletion) {
        const toolHooks = factory.class.forDeletion({
          outputRoot: this.outputRoot,
          relativeDirPath: paths.relativeDirPath,
          relativeFilePath: paths.relativeFilePath,
          global: this.global,
        });
        const auxiliaryFiles =
          (await factory.class.getDeletableAuxiliaryFiles?.({
            outputRoot: this.outputRoot,
            global: this.global,
          })) ?? [];
        const list = [
          ...(toolHooks.isDeletable?.() !== false ? [toolHooks] : []),
          ...auxiliaryFiles.filter((file) => file.isDeletable()),
        ];
        this.logger.debug(
          `Successfully loaded ${list.length} ${this.toolTarget} hooks files for deletion`,
        );
        return list;
      }

      const toolHooks = await factory.class.fromFile({
        outputRoot: this.outputRoot,
        validate: true,
        global: this.global,
        logger: this.logger,
      });
      this.logger.debug(`Successfully loaded 1 ${this.toolTarget} hooks file`);
      return [toolHooks];
    } catch (error) {
      const msg = `Failed to load hooks files for tool target: ${this.toolTarget}: ${formatError(error)}`;
      // The tool's own config simply not being there yet is the normal first
      // run, so it stays at debug. Matching on `code` rather than on the
      // message keeps a wrapped or localized error from being read as absence.
      if (isFileNotFoundError(error)) {
        this.logger.debug(msg);
      } else {
        this.logger.error(msg);
      }
      return [];
    }
  }

  async convertRulesyncFilesToToolFiles(rulesyncFiles: RulesyncFile[]): Promise<ToolFile[]> {
    const rulesyncHooks = rulesyncFiles.find((f): f is RulesyncHooks => f instanceof RulesyncHooks);
    if (!rulesyncHooks) {
      throw new Error(`No ${RULESYNC_HOOKS_RELATIVE_FILE_PATH} found.`);
    }

    const factory = toolHooksFactories.get(this.toolTarget);
    if (!factory) throw new Error(`Unsupported tool target: ${this.toolTarget}`);

    const config = rulesyncHooks.getJson();
    const sharedHooks = config.hooks;
    const overrideKey = HOOKS_OVERRIDE_KEY_ALIASES[this.toolTarget] ?? this.toolTarget;
    const overrideHooks = (config[overrideKey] as { hooks?: unknown } | undefined)?.hooks ?? {};
    const effectiveHooks = { ...sharedHooks, ...overrideHooks };

    // Warn about unsupported events
    {
      const skipped = unsupportedEventNames({ factory, sharedHooks, effectiveHooks });
      if (skipped.length > 0) {
        this.logger.warn(
          `Skipped hook event(s) for ${this.toolTarget} (not supported): ${skipped.join(", ")}`,
        );
      }
    }

    // Warn about unsupported hook types
    {
      const supportedHookTypes: Set<string> = new Set(factory.supportedHookTypes);
      const unsupportedTypeToEvents = new Map<string, Set<string>>();
      for (const [event, defs] of Object.entries(effectiveHooks)) {
        for (const def of defs as unknown[]) {
          const hookDef = def as { type?: string };
          const hookType = hookDef.type ?? "command";
          if (!supportedHookTypes.has(hookType)) {
            const events = unsupportedTypeToEvents.get(hookType) ?? new Set<string>();
            events.add(event);
            unsupportedTypeToEvents.set(hookType, events);
          }
        }
      }

      for (const [hookType, events] of unsupportedTypeToEvents) {
        this.logger.warn(
          `Skipped ${hookType}-type hook(s) for ${this.toolTarget} (not supported): ${Array.from(events).join(", ")}`,
        );
      }
    }

    this.warnAboutDroppedPerHookFields({ factory, sharedHooks, effectiveHooks });

    // Warn about unsupported matcher
    const eventsWithUnsupportedMatcher = unsupportedMatcherEventNames({ factory, effectiveHooks });
    if (eventsWithUnsupportedMatcher.length > 0) {
      this.logger.warn(
        `Skipped matcher hook(s) for ${this.toolTarget} (not supported): ${eventsWithUnsupportedMatcher.join(", ")}`,
      );
    }

    const toolHooks = await factory.class.fromRulesyncHooks({
      outputRoot: this.outputRoot,
      rulesyncHooks,
      validate: true,
      global: this.global,
      preserveUnowned: this.preserveUnownedHooks,
      // The converter is shared by every target, so its warnings say what is
      // wrong but not which file is being written. Every other warning here
      // names the tool, and one generate run walks all of them.
      logger: withToolTargetPrefix({ logger: this.logger, toolTarget: this.toolTarget }),
    });

    const result: ToolFile[] = [toolHooks];
    const auxiliaryFiles = await factory.class.getAuxiliaryFiles?.({
      outputRoot: this.outputRoot,
      global: this.global,
      toolHooks,
      logger: withToolTargetPrefix({ logger: this.logger, toolTarget: this.toolTarget }),
    });
    if (auxiliaryFiles && auxiliaryFiles.length > 0) {
      result.push(...auxiliaryFiles);
    }

    return result;
  }

  /**
   * Warns about canonical per-hook fields that this target's hooks format
   * cannot express, so a hook does not silently change behavior on generation.
   * Only canonical definitions are considered: a tool-native field inside an
   * override block is passed through verbatim and honored by that tool.
   */
  private warnAboutDroppedPerHookFields(params: {
    factory: ToolHooksFactory;
    sharedHooks: HooksConfig["hooks"];
    effectiveHooks: HooksConfig["hooks"];
  }): void {
    const { factory, sharedHooks, effectiveHooks } = params;
    // Warn that `enabled: false` cannot be expressed by targets whose hooks
    // format carries no per-definition on-disk enable flag (`kiro-ide`,
    // `kiro-cli` and `zcode` do); everywhere else the hook is emitted as an
    // ordinary, active hook, so a user who paused one hook would otherwise see
    // it keep firing with no explanation.
    if (!PER_HOOK_ENABLED_TARGETS.has(this.toolTarget)) {
      const eventsWithDisabledHooks = emittedEventsWithHook({
        factory,
        sharedHooks,
        effectiveHooks,
        predicate: (def) => def.enabled === false,
      });
      if (eventsWithDisabledHooks.length > 0) {
        this.logger.warn(
          `Emitting "enabled: false" hook(s) as active for ${this.toolTarget} (only the kiro-cli / kiro-ide / zcode hooks formats support the flag): ${eventsWithDisabledHooks.join(", ")}`,
        );
      }
    }

    // Same idea for the Kiro `confirm` prompt: it asks the user
    // before the command runs, so a target without it would run the hook
    // unconditionally with no explanation.
    if (!PER_HOOK_CONFIRM_TARGETS.has(this.toolTarget)) {
      const eventsWithConfirmHooks = emittedEventsWithHook({
        factory,
        sharedHooks,
        effectiveHooks,
        predicate: (def) => def.confirm !== undefined,
      });
      if (eventsWithConfirmHooks.length > 0) {
        this.logger.warn(
          `Emitting hook(s) without their "confirm" prompt for ${this.toolTarget} (only the kiro-cli / kiro-ide hooks formats support it): ${eventsWithConfirmHooks.join(", ")}`,
        );
      }
    }
  }

  async convertToolFilesToRulesyncFiles(toolFiles: ToolFile[]): Promise<RulesyncFile[]> {
    const hooks = toolFiles.filter((f): f is ToolHooks => f instanceof ToolHooks);
    // Prefixed for the same reason as the generate direction: `rulesync import`
    // walks several targets, and the converter's warnings do not name one.
    const logger = withToolTargetPrefix({ logger: this.logger, toolTarget: this.toolTarget });
    return hooks.map((h) => h.toRulesyncHooks({ logger }));
  }

  static getToolTargets({
    global = false,
    importOnly = false,
  }: { global?: boolean; importOnly?: boolean } = {}): ToolTarget[] {
    if (global) {
      return importOnly
        ? hooksProcessorToolTargetsGlobalImportable
        : hooksProcessorToolTargetsGlobal;
    }
    return importOnly ? hooksProcessorToolTargetsImportable : hooksProcessorToolTargets;
  }
}
