import { join } from "node:path";

import {
  AUGMENTCODE_DIR,
  AUGMENTCODE_SETTINGS_FILE_NAME,
} from "../../constants/augmentcode-paths.js";
import { ValidationResult } from "../../types/ai-file.js";
import { isMcpServers } from "../../types/mcp.js";
import {
  parseAugmentcodeSettingsDocument,
  readAugmentcodeSettingsWithLocalOverlay,
} from "../../utils/augmentcode-settings.js";
import { readFileContentOrNull } from "../../utils/file.js";
import { applySharedConfigPatch, sharedConfigFileKey } from "../shared/shared-config-gateway.js";
import { RulesyncMcp } from "./rulesync-mcp.js";
import {
  ToolMcp,
  ToolMcpForDeletionParams,
  ToolMcpFromFileParams,
  ToolMcpFromRulesyncMcpParams,
  ToolMcpParams,
  ToolMcpSettablePaths,
} from "./tool-mcp.js";

function parseAugmentcodeSettings(
  fileContent: string,
  relativeDirPath: string,
  relativeFilePath: string,
): Record<string, unknown> {
  return parseAugmentcodeSettingsDocument({
    fileContent,
    configPath: join(relativeDirPath, relativeFilePath),
  });
}

/**
 * AugmentCode (Auggie CLI) MCP servers.
 *
 * MCP servers are persisted in the shared settings file `.augment/settings.json`
 * at either scope: the committed workspace file for team-shared servers (project)
 * or `~/.augment/settings.json` (global). That same file also holds `hooks` and
 * `toolPermissions`, so generation merges the `mcpServers` block into the
 * existing settings instead of overwriting it, and the file is never deleted. On
 * project-scope import the gitignored `.augment/settings.local.json` overrides
 * file is overlaid on top (the same layering the hooks/permissions adapters use).
 *
 * @see https://docs.augmentcode.com/cli/config
 */
export class AugmentcodeMcp extends ToolMcp {
  private readonly json: Record<string, unknown>;

  constructor(params: ToolMcpParams) {
    super(params);
    if (this.fileContent !== undefined) {
      this.json = parseAugmentcodeSettings(
        this.fileContent,
        this.relativeDirPath,
        this.relativeFilePath,
      );
    } else {
      this.json = {};
    }
  }

  getJson(): Record<string, unknown> {
    return this.json;
  }

  override isDeletable(): boolean {
    // settings.json is shared with the hooks and permissions features, so it
    // must never be removed wholesale; clearing MCP happens via an in-place
    // merge instead.
    return false;
  }

  static getSettablePaths(_options?: { global?: boolean }): ToolMcpSettablePaths {
    return {
      relativeDirPath: AUGMENTCODE_DIR,
      relativeFilePath: AUGMENTCODE_SETTINGS_FILE_NAME,
    };
  }

  static async fromFile({
    outputRoot = process.cwd(),
    validate = true,
    global = false,
    logger,
  }: ToolMcpFromFileParams): Promise<AugmentcodeMcp> {
    const paths = this.getSettablePaths({ global });
    // On project-scope import, overlay the gitignored
    // `.augment/settings.local.json` ON TOP of `settings.json` so machine-local
    // MCP overrides are picked up. The overrides file is project-only (there is
    // no global `~/.augment/settings.local.json`), so it is skipped in global
    // mode.
    const fileContent = await readAugmentcodeSettingsWithLocalOverlay({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      baseFileName: paths.relativeFilePath,
      baseFallbackContent: "{}",
      includeLocalOverlay: !global,
      logger,
    });
    const json = parseAugmentcodeSettings(
      fileContent,
      paths.relativeDirPath,
      paths.relativeFilePath,
    );
    const newJson = { ...json, mcpServers: json.mcpServers ?? {} };

    return new AugmentcodeMcp({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent: JSON.stringify(newJson, null, 2),
      validate,
      global,
    });
  }

  static async fromRulesyncMcp({
    outputRoot = process.cwd(),
    rulesyncMcp,
    validate = true,
    global = false,
    logger,
  }: ToolMcpFromRulesyncMcpParams): Promise<AugmentcodeMcp> {
    const paths = this.getSettablePaths({ global });

    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    const existingContent = (await readFileContentOrNull(filePath)) ?? JSON.stringify({}, null, 2);

    return new AugmentcodeMcp({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent: applySharedConfigPatch({
        fileKey: sharedConfigFileKey(paths),
        feature: "mcp",
        existingContent,
        patch: { mcpServers: rulesyncMcp.getMcpServers() },
        filePath,
        logger,
      }),
      validate,
      global,
    });
  }

  toRulesyncMcp(): RulesyncMcp {
    const mcpServers = isMcpServers(this.json.mcpServers) ? this.json.mcpServers : {};
    // Do not spread the full settings JSON: tool-specific keys (hooks,
    // toolPermissions, etc.) must not leak into rulesync mcp.json.
    return this.toRulesyncMcpDefault({
      fileContent: JSON.stringify({ mcpServers }, null, 2),
    });
  }

  validate(): ValidationResult {
    return { success: true, error: null };
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    relativeFilePath,
    global = false,
  }: ToolMcpForDeletionParams): AugmentcodeMcp {
    // The shared settings file is never deleted (isDeletable() === false), but
    // forDeletion must still return a well-formed instance.
    return new AugmentcodeMcp({
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      fileContent: JSON.stringify({ mcpServers: {} }, null, 2),
      validate: false,
      global,
    });
  }
}
