const HermesCommandSpecSchema = z.object({
  slug: z.string(),
  description: z.string(),
  prompt: z.string(),
});

type HermesCommandSpec = z.infer<typeof HermesCommandSpecSchema>;

function hermesSlashName(value: string): string {
  return value
    .toLowerCase()
    .replace(/[ _]/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-{2,}/g, "-")
    .replace(/^-|-$/g, "");
}

function getPluginManifestContent(): string {
  return [
    "name: rulesync-commands",
    'version: "1.0.0"',
    "description: Exposes RuleSync commands as Hermes native slash commands.",
    "",
  ].join("\n");
}

function getPluginInitContent(): string {
  return `"""RuleSync-generated Hermes slash commands."""

import json
from pathlib import Path


COMMANDS_DIR = Path(__file__).resolve().parents[2] / "rulesync" / "commands"


def _load_commands():
    if not COMMANDS_DIR.exists():
        return []

    commands = []
    for path in sorted(COMMANDS_DIR.glob("*.json")):
        try:
            command = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(command, dict):
            commands.append(command)
    return commands


def _register_command(ctx, command):
    slug = command.get("slug")
    if not slug:
        return

    description = command.get("description") or f"Run the {slug} RuleSync command."
    prompt = command.get("prompt") or ""

    def handler(args=None, **kwargs):
        del kwargs
        raw_args = ""
        if isinstance(args, dict):
            raw_args = args.get("args") or args.get("context") or args.get("prompt") or ""
        elif args is not None:
            raw_args = str(args)

        context_parts = [prompt] if prompt else []
        if raw_args:
            context_parts.append(f"User arguments:\\n{raw_args}")

        # delegate_task takes no model-facing "toolsets" argument: the child
        # inherits the parent's enabled toolsets. "tasks" is the only shape its
        # schema advertises; a top-level "goal" is an unadvertised legacy path.
        return ctx.dispatch_tool(
            "delegate_task",
            {
                "tasks": [
                    {
                        "goal": description,
                        "context": "\\n\\n".join(context_parts),
                    },
                ],
            },
        )

    ctx.register_command(slug, handler, description)


def register(ctx):
    for command in _load_commands():
        _register_command(ctx, command)
`;
}

function getEnabledPluginConfigContent({
  currentContent,
  global,
}: {
  currentContent: string;
  global: boolean;
}): string {
  const config = parseSharedConfig({ format: "yaml", fileContent: currentContent });
  const plugins =
    config.plugins && typeof config.plugins === "object"
      ? (config.plugins as Record<string, unknown>)
      : {};
  const enabled = Array.isArray(plugins.enabled) ? plugins.enabled : [];

  return applySharedConfigPatch({
    fileKey: getHermesagentConfigSharedFileKey({ global }),
    feature: "commands",
    existingContent: currentContent,
    patch: {
      plugins: {
        ...plugins,
        enabled: Array.from(new Set([...enabled, "rulesync-commands"])),
      },
    },
  });
}

export function getDisabledHermesCommandsPluginConfigContent({
  currentContent,
  global,
}: {
  currentContent: string;
  global: boolean;
}): string {
  const config = parseSharedConfig({ format: "yaml", fileContent: currentContent });
  const plugins =
    config.plugins && typeof config.plugins === "object"
      ? (config.plugins as Record<string, unknown>)
      : {};
  const enabled = Array.isArray(plugins.enabled) ? plugins.enabled : [];

  return applySharedConfigPatch({
    fileKey: getHermesagentConfigSharedFileKey({ global }),
    feature: "commands",
    existingContent: currentContent,
    patch: {
      plugins: {
        ...plugins,
        enabled: enabled.filter((plugin) => plugin !== "rulesync-commands"),
      },
    },
  });
}

class HermesagentCommandAuxiliaryFile extends ToolFile {
  validate(): ValidationResult {
    return { success: true, error: null };
  }

  /**
   * Whether this auxiliary file is the one at `relativeFilePath`, comparing
   * against the scope-resolved location of that canonical `.hermes/...` path.
   */
  private matchesPath(relativeFilePath: string): boolean {
    return (
      this.getRelativePathFromCwd() ===
      toPosixPath(getHermesagentRelativeFilePath({ global: this.global, relativeFilePath }))
    );
  }

  shouldMergeExistingFileContent(): boolean {
    return this.matchesPath(HERMESAGENT_CONFIG_FILE_PATH);
  }

  setFileContent(newFileContent: string): void {
    if (this.matchesPath(HERMESAGENT_CONFIG_FILE_PATH)) {
      super.setFileContent(
        getEnabledPluginConfigContent({ currentContent: newFileContent, global: this.global }),
      );
      return;
    }
    super.setFileContent(newFileContent);
  }

  getFileContent(): string {
    if (this.matchesPath(HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_MANIFEST_PATH)) {
      return getPluginManifestContent();
    }
    if (this.matchesPath(HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_INIT_PATH)) {
      return getPluginInitContent();
    }
    if (this.matchesPath(HERMESAGENT_CONFIG_FILE_PATH)) {
      return getEnabledPluginConfigContent({
        currentContent: super.getFileContent(),
        global: this.global,
      });
    }
    return super.getFileContent();
  }
}

export class HermesagentCommand extends ToolCommand {
  static override isTargetedByRulesyncCommand(rulesyncCommand: RulesyncCommand): boolean {
    return this.isTargetedByRulesyncCommandDefault({ rulesyncCommand, toolTarget: "hermesagent" });
  }

  static getSettablePaths({ global = false }: { global?: boolean } = {}): {
    relativeDirPath: string;
  } {
    return {
      relativeDirPath: getHermesagentRelativeDirPath({
        global,
        relativeDirPath: HERMESAGENT_RULESYNC_COMMANDS_DIR_PATH,
      }),
    };
  }

  /**
   * `config.yaml` under every spelling the global profile root can take.
   * @see getHermesagentSharedConfigWritePaths
   */
  static getExtraSharedWritePaths(): SharedWritePath[] {
    return getHermesagentSharedConfigWritePaths();
  }

  static async validateRulesyncCommands({
    inputRoots,
    rulesyncCommands,
  }: {
    inputRoots: readonly string[];
    rulesyncCommands: RulesyncCommand[];
  }): Promise<void> {
    const commandSlugs = new Set<string>();
    const commandOrigins = new Map<string, string>();
    for (const command of rulesyncCommands.filter((candidate) =>
      this.isTargetedByRulesyncCommand(candidate),
    )) {
      const origin = command.getRelativeFilePath();
      const slug = hermesSlashName(basename(origin, ".md"));
      if (!slug) {
        throw new Error(`Hermes command "${origin}" does not produce a valid slash name.`);
      }
      const firstOrigin = commandOrigins.get(slug);
      if (firstOrigin && firstOrigin !== origin) {
        throw new Error(
          `Hermes command slash-name collision: "${firstOrigin}" and "${origin}" both normalize to "${slug}".`,
        );
      }
      commandOrigins.set(slug, origin);
      commandSlugs.add(slug);
    }
    // Skills from any input root can collide with commands. Track the origin
    // root of each skill so a same-named skill in a later root shadows the
    // earlier one (matching the overlay semantics used by the skills processor).
    const skillsByName = new Map<
      string,
      { rulesyncSkill: RulesyncSkill; dirName: string; rootPath: string }
    >();
    for (const rootPath of inputRoots) {
      const skillsRoot = join(rootPath, SKILLS_FEATURE_SUBDIR);
      // Read rather than globbed: a glob for a nested `SKILL.md` builds a
      // two-segment directory name that no `AiDir` accepts, and it spells a
      // name holding a backslash as two segments as well, so a repository
      // holding either used to fail the whole run here.
      const dirNames = await listSkillDirNames(skillsRoot);
      // Roots stay sequential so a later root still shadows an earlier one, but
      // the skills inside one root are independent and load concurrently.
      const loaded = await Promise.all(
        dirNames.map(async (dirName) => {
          const rulesyncSkill = await RulesyncSkill.fromDir({
            outputRoot: rootPath,
            relativeDirPath: SKILLS_FEATURE_SUBDIR,
            dirName,
          });
          return { rulesyncSkill, dirName, rootPath };
        }),
      );
      for (const entry of loaded) {
        // Key on the case-folded name so shadowing matches what the skills
        // processor actually does across roots; a case-only variant in a later
        // root replaces the earlier skill instead of being counted twice.
        skillsByName.set(caseFoldIdentity(entry.dirName), entry);
      }
    }
    const collisions = [...skillsByName.values()]
      .map(({ rulesyncSkill }) => rulesyncSkill)
      .filter((skill) => HermesagentSkill.isTargetedByRulesyncSkill(skill))
      .map((skill) => hermesSlashName(skill.getFrontmatter().name))
      .filter((slug) => commandSlugs.has(slug));
    if (collisions.length > 0) {
      throw new Error(
        `Hermes command and skill slash-name collision: ${[...new Set(collisions)].toSorted().join(", ")}`,
      );
    }
  }

  static async getAuxiliaryFiles({
    toolCommands,
    outputRoot,
    global = false,
    forDeletion = false,
  }: {
    toolCommands: ToolCommand[];
    outputRoot?: string;
    global?: boolean;
    forDeletion?: boolean;
  }): Promise<ToolFile[]> {
    if (toolCommands.length === 0 && !forDeletion) return [];
    const pluginDirPath = getHermesagentRelativeDirPath({
      global,
      relativeDirPath: HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_DIR_PATH,
    });
    const pluginFiles: ToolFile[] = [
      new HermesagentCommandAuxiliaryFile({
        outputRoot,
        relativeDirPath: pluginDirPath,
        relativeFilePath: basename(HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_MANIFEST_PATH),
        fileContent: "",
        global,
      }),
      new HermesagentCommandAuxiliaryFile({
        outputRoot,
        relativeDirPath: pluginDirPath,
        relativeFilePath: basename(HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_OWNERSHIP_PATH),
        fileContent: "Generated and owned by RuleSync.\n",
        global,
      }),
      new HermesagentCommandAuxiliaryFile({
        outputRoot,
        relativeDirPath: pluginDirPath,
        relativeFilePath: basename(HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_INIT_PATH),
        fileContent: "",
        global,
      }),
    ];
    if (forDeletion) return pluginFiles;
    return [
      ...pluginFiles,
      new HermesagentCommandAuxiliaryFile({
        outputRoot,
        relativeDirPath: getHermesagentRelativeDirPath({
          global,
          relativeDirPath: HERMESAGENT_GLOBAL_DIR,
        }),
        relativeFilePath: basename(HERMESAGENT_CONFIG_FILE_PATH),
        fileContent: "",
        global,
      }),
    ];
  }

  static async canDeleteAuxiliaryFiles({
    outputRoot,
    global = false,
  }: {
    outputRoot: string;
    global?: boolean;
  }): Promise<boolean> {
    const marker = await readFileContentOrNull(
      join(
        outputRoot,
        getHermesagentRelativeFilePath({
          global,
          relativeFilePath: HERMESAGENT_RULESYNC_COMMANDS_PLUGIN_OWNERSHIP_PATH,
        }),
      ),
    );
    return marker === "Generated and owned by RuleSync.\n";
  }

  static override async fromFile({
    global = false,
    outputRoot = process.cwd(),
    relativeFilePath,
    validate = true,
  }: ToolCommandFromFileParams): Promise<HermesagentCommand> {
    const relativeDirPath = this.getSettablePaths({ global }).relativeDirPath;
    return new HermesagentCommand({
      fileContent: await readFile(join(outputRoot, relativeDirPath, relativeFilePath), "utf8"),
      global,
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      validate,
    });
  }

  static override forDeletion({
    global = false,
    outputRoot,
    relativeDirPath,
    relativeFilePath,
  }: ToolCommandForDeletionParams): HermesagentCommand {
    return new HermesagentCommand({
      fileContent: "",
      global,
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      validate: false,
    });
  }

  static override fromRulesyncCommand({
    outputRoot,
    rulesyncCommand,
    global = false,
  }: ToolCommandFromRulesyncCommandParams): HermesagentCommand {
    const slug = hermesSlashName(basename(rulesyncCommand.getRelativeFilePath(), ".md"));
    const spec: HermesCommandSpec = {
      slug,
      description: rulesyncCommand.getFrontmatter().description ?? `${slug} command`,
      prompt: rulesyncCommand.getBody(),
    };
    return new HermesagentCommand({
      outputRoot,
      relativeDirPath: this.getSettablePaths({ global }).relativeDirPath,
      relativeFilePath: `${slug}.json`,
      fileContent: `${JSON.stringify(spec, null, 2)}\n`,
      global,
    });
  }

  validate(): ValidationResult {
    try {
      const result = HermesCommandSpecSchema.safeParse(JSON.parse(this.fileContent));
      if (result.success) return { success: true, error: null };
      return { success: false, error: result.error };
    } catch (error) {
      return { success: false, error: error instanceof Error ? error : new Error(String(error)) };
    }
  }

  toRulesyncCommand(): RulesyncCommand {
    const spec = HermesCommandSpecSchema.parse(JSON.parse(this.fileContent));
    return new RulesyncCommand({
      relativeDirPath: RULESYNC_COMMANDS_RELATIVE_DIR_PATH,
      relativeFilePath: `${spec.slug}.md`,
      frontmatter: { description: spec.description },
      body: spec.prompt,
      fileContent: "",
      outputRoot: getHermesagentRulesyncOutputRoot({
        nativeOutputRoot: this.outputRoot,
        global: this.global,
      }),
    });
  }
}
