import { join } from "node:path";

import { CURSOR_DIR, CURSOR_HOOKS_FILE_NAME } from "../../constants/cursor-paths.js";
import type { ValidationResult } from "../../types/ai-file.js";
import type { HooksConfig } from "../../types/hooks.js";
import {
  CURSOR_HOOK_EVENTS,
  CURSOR_TO_CANONICAL_EVENT_NAMES,
  CANONICAL_TO_CURSOR_EVENT_NAMES,
} from "../../types/hooks.js";
import type { ToolFile } from "../../types/tool-file.js";
import { readFileContent, readFileContentOrNull } from "../../utils/file.js";
import type { Logger } from "../../utils/logger.js";
import { lookupOwn } from "../../utils/own-lookup.js";
import { HOOKS_OWNERSHIP_LOCK_FILE_NAME, parseHooksOwnershipLock } from "./hooks-ownership-lock.js";
import { mergeGeneratedHookLists } from "./preserve-unowned-hook-commands.js";
import type { RulesyncHooks } from "./rulesync-hooks.js";
import { buildImportedHooksConfig } from "./tool-hooks-converter.js";
import {
  ToolHooks,
  type ToolHooksForDeletionParams,
  type ToolHooksFromFileParams,
  type ToolHooksFromRulesyncHooksParams,
  type ToolHooksParams,
  type ToolHooksSettablePaths,
} from "./tool-hooks.js";

export type CursorHooksConstructorParams = ToolHooksParams & {
  rulesyncHooks?: RulesyncHooks;
};

export class CursorHooks extends ToolHooks {
  constructor(params: CursorHooksConstructorParams) {
    const { rulesyncHooks: _r, ...rest } = params;
    super({
      ...rest,
      fileContent: rest.fileContent ?? "{}",
    });
  }

  static getSettablePaths(_options: { global?: boolean } = {}): ToolHooksSettablePaths {
    // Cursor uses the same `.cursor/hooks.json` filename for both project and
    // global scope. The only thing that changes is the resolution root
    // (project root vs. home directory), which the harness handles by
    // overriding `outputRoot` when `--global` is passed.
    // Reference: https://cursor.com/docs/agent/hooks
    return {
      relativeDirPath: CURSOR_DIR,
      relativeFilePath: CURSOR_HOOKS_FILE_NAME,
    };
  }

  static async fromFile({
    outputRoot = process.cwd(),
    validate = true,
    global = false,
  }: ToolHooksFromFileParams): Promise<CursorHooks> {
    const paths = CursorHooks.getSettablePaths({ global });
    const fileContent = await readFileContent(
      join(outputRoot, paths.relativeDirPath, paths.relativeFilePath),
    );
    return new CursorHooks({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent,
      validate,
    });
  }

  static async fromRulesyncHooks({
    outputRoot = process.cwd(),
    rulesyncHooks,
    validate = true,
    global = false,
    preserveUnowned = false,
    logger,
  }: ToolHooksFromRulesyncHooksParams & { global?: boolean }): Promise<CursorHooks> {
    const config = rulesyncHooks.getJson();
    const cursorSupported: Set<string> = new Set(CURSOR_HOOK_EVENTS);
    const sharedHooks: HooksConfig["hooks"] = {};
    for (const [event, defs] of Object.entries(config.hooks)) {
      if (cursorSupported.has(event)) {
        sharedHooks[event] = defs;
      }
    }
    const mergedHooks: HooksConfig["hooks"] = {
      ...sharedHooks,
      ...config.cursor?.hooks,
    };
    // Map canonical event names to Cursor event names.
    // Currently an identity mapping (camelCase → camelCase), but this loop maintains
    // architectural consistency with other tool converters (Claude, Factory Droid) and
    // becomes essential if Cursor's event naming diverges from canonical in the future.
    const mappedHooks: HooksConfig["hooks"] = {};
    // Cursor only documents `command` and `prompt` hooks; other canonical
    // types are skipped (the HooksProcessor warns about them).
    const cursorSupportedTypes = new Set(["command", "prompt"]);
    for (const [eventName, defs] of Object.entries(mergedHooks)) {
      const cursorEventName =
        lookupOwn({ record: CANONICAL_TO_CURSOR_EVENT_NAMES, key: eventName }) ?? eventName;
      const mappedDefs = defs
        .filter((def) => cursorSupportedTypes.has(def.type ?? "command"))
        .map((def) => ({
          ...(def.type !== undefined && def.type !== null && { type: def.type }),
          ...(def.command !== undefined && def.command !== null && { command: def.command }),
          ...(def.timeout !== undefined && def.timeout !== null && { timeout: def.timeout }),
          ...(def.loop_limit !== undefined && { loop_limit: def.loop_limit }),
          ...(def.matcher !== undefined && def.matcher !== null && { matcher: def.matcher }),
          ...(def.prompt !== undefined && def.prompt !== null && { prompt: def.prompt }),
          // Prompt hooks accept an optional `model` overriding the fast model
          // that evaluates the condition. https://cursor.com/docs/hooks
          ...(def.type === "prompt" &&
            def.model !== undefined &&
            def.model !== null && { model: def.model }),
          ...(def.failClosed !== undefined &&
            def.failClosed !== null && {
              failClosed: def.failClosed,
            }),
        }));
      if (mappedDefs.length > 0) {
        mappedHooks[cursorEventName] = mappedDefs;
      }
    }
    const paths = CursorHooks.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    const existingContent = (await readFileContentOrNull(filePath)) ?? "";
    const previouslyOwned = preserveUnowned
      ? parseHooksOwnershipLock(
          await readFileContentOrNull(
            join(outputRoot, paths.relativeDirPath, HOOKS_OWNERSHIP_LOCK_FILE_NAME),
          ),
        )
      : undefined;
    const merged = mergeGeneratedHookLists({
      existingContent,
      generatedHooks: mappedHooks as Record<string, unknown[]>,
      shape: "flat",
      preserveUnowned,
      previouslyOwned,
      logger,
    });
    const cursorConfig = {
      version: config.version ?? 1,
      hooks: merged.hooks,
    };
    const fileContent = JSON.stringify(cursorConfig, null, 2);
    return new CursorHooks({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent,
      ownedHookRefs: preserveUnowned ? merged.owned : undefined,
      validate,
      rulesyncHooks,
    });
  }

  static override supportsPreserveUnowned(): boolean {
    return true;
  }

  static override async getAuxiliaryFiles({
    toolHooks,
  }: {
    outputRoot?: string;
    global?: boolean;
    toolHooks?: ToolHooks;
    logger?: Logger;
  } = {}): Promise<ToolFile[]> {
    return toolHooks instanceof CursorHooks ? toolHooks.getOwnershipLockFiles() : [];
  }

  toRulesyncHooks(): RulesyncHooks {
    const content = this.getFileContent();
    const parsed: { version?: number; hooks?: HooksConfig["hooks"] } = JSON.parse(content);
    const cursorHooks = parsed.hooks ?? {};
    // Map Cursor event names back to canonical event names.
    // Currently identity but kept explicit for forward compatibility
    // (see CANONICAL_TO_CURSOR_EVENT_NAMES in types/hooks.ts).
    const canonicalHooks: HooksConfig["hooks"] = {};
    for (const [cursorEventName, defs] of Object.entries(cursorHooks)) {
      const eventName =
        lookupOwn({ record: CURSOR_TO_CANONICAL_EVENT_NAMES, key: cursorEventName }) ??
        cursorEventName;
      canonicalHooks[eventName] = defs;
    }
    const version = parsed.version ?? 1;
    return this.toRulesyncHooksDefault({
      fileContent: JSON.stringify(
        buildImportedHooksConfig({ hooks: canonicalHooks, overrideKey: "cursor", version }),
        null,
        2,
      ),
    });
  }

  validate(): ValidationResult {
    return { success: true, error: null };
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    relativeFilePath,
  }: ToolHooksForDeletionParams): CursorHooks {
    return new CursorHooks({
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      fileContent: "{}",
      validate: false,
    });
  }
}
