import { AiFileFromFileParams, AiFileParams } from "../../types/ai-file.js";
import { ToolFile } from "../../types/tool-file.js";
import { ToolTarget } from "../../types/tool-targets.js";
import type { Logger } from "../../utils/logger.js";
import { RulesyncSubagent } from "./rulesync-subagent.js";

export type ToolSubagentFromRulesyncSubagentParams = Omit<
  AiFileParams,
  "fileContent" | "relativeFilePath"
> & {
  rulesyncSubagent: RulesyncSubagent;
  global?: boolean;
  /** Used to report frontmatter a target drops or rewrites during generation. */
  logger?: Logger;
};

export type ToolSubagentSettablePaths = {
  relativeDirPath: string;
  /**
   * Additional directories to scan when *importing* subagents, beyond
   * `relativeDirPath`. Generation and orphan deletion always target only
   * `relativeDirPath`; these extra roots are read-only discovery locations
   * (e.g. Junie also reads the cross-tool `.agents/` directory). Omitted by
   * tools that have a single subagent directory.
   */
  importDirPaths?: Array<
    | string
    | {
        outputRoot: string;
        relativeDirPath: string;
      }
  >;
  /**
   * Set when a tool's subagents all live in one file rather than in a
   * directory of per-agent files (e.g. Pool's `settings.yaml`). Consumers that
   * would otherwise assume the whole directory is rulesync's — the gitignore
   * and shared-file derivations, for one — use it to narrow to that single
   * file.
   */
  relativeFilePath?: string;
};

export type ToolSubagentFromFileParams = AiFileFromFileParams & {
  global?: boolean;
  /** Receives the warnings of a tool whose file may carry entries it skips. */
  logger?: Logger;
};

export type ToolSubagentForDeletionParams = {
  outputRoot?: string;
  relativeDirPath: string;
  relativeFilePath: string;
  global?: boolean;
};
export abstract class ToolSubagent extends ToolFile {
  static getSettablePaths(): ToolSubagentSettablePaths {
    throw new Error("Please implement this method in the subclass.");
  }

  static async fromFile(_params: ToolSubagentFromFileParams): Promise<ToolSubagent> {
    throw new Error("Please implement this method in the subclass.");
  }

  /**
   * Create a minimal instance for deletion purposes.
   * This method does not read or parse file content, making it safe to use
   * even when files have old/incompatible formats.
   */
  static forDeletion(_params: ToolSubagentForDeletionParams): ToolSubagent {
    throw new Error("Please implement this method in the subclass.");
  }

  static fromRulesyncSubagent(_params: ToolSubagentFromRulesyncSubagentParams): ToolSubagent {
    throw new Error("Please implement this method in the subclass.");
  }

  abstract toRulesyncSubagent(): RulesyncSubagent;

  /** Identity used to resolve duplicate imports across discovery roots. */
  getImportIdentity(): string {
    return this.getRelativeFilePath();
  }

  /**
   * Optional fan-out hook for tools whose native format aggregates several
   * subagents into one file (e.g. Roo's `.roomodes`). When implemented, the
   * processor uses it during import so one tool file yields N rulesync
   * subagents. Tools with a one-file-per-subagent layout omit it.
   */
  toRulesyncSubagents?(): RulesyncSubagent[];

  static isTargetedByRulesyncSubagent(_rulesyncSubagent: RulesyncSubagent): boolean {
    throw new Error("Please implement this method in the subclass.");
  }

  protected static isTargetedByRulesyncSubagentDefault({
    rulesyncSubagent,
    toolTarget,
  }: {
    rulesyncSubagent: RulesyncSubagent;
    toolTarget: ToolTarget;
  }): boolean {
    const targets = rulesyncSubagent.getFrontmatter().targets;
    if (!targets) {
      return true;
    }

    if (targets.includes("*")) {
      return true;
    }

    if (targets.includes(toolTarget)) {
      return true;
    }

    return false;
  }

  protected static filterToolSpecificSection(
    rawSection: Record<string, unknown>,
    excludeFields: string[],
  ): Record<string, unknown> {
    const filtered: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(rawSection)) {
      if (!excludeFields.includes(key)) {
        filtered[key] = value;
      }
    }
    return filtered;
  }
}
