import { basename, join } from "node:path";

import { z } from "zod/mini";

import { KIRO_AGENTS_DIR_PATH } from "../../constants/kiro-paths.js";
import { RULESYNC_SUBAGENTS_RELATIVE_DIR_PATH } from "../../constants/rulesync-paths.js";
import { AiFileParams, ValidationResult } from "../../types/ai-file.js";
import { readFileContent } from "../../utils/file.js";
import { RulesyncSubagent, RulesyncSubagentFrontmatter } from "./rulesync-subagent.js";
import {
  ToolSubagent,
  ToolSubagentForDeletionParams,
  ToolSubagentFromFileParams,
  ToolSubagentFromRulesyncSubagentParams,
  ToolSubagentSettablePaths,
} from "./tool-subagent.js";

// Agent configs written before CLI V3 key hooks by event (`{ "agentSpawn": [...] }`);
// `/upgrade-agent` converts them to "the array format the v3 schema requires",
// and the V3 field reference describes inline hooks as "same schema as
// `.kiro/hooks/`" (`{ "version": "v1", "hooks": [...] }`). Accept all three so
// an upgraded agent still imports.
// https://kiro.dev/docs/cli/v3/upgrade-agent/
// https://kiro.dev/docs/cli/v3/agent-config/
const KiroCliSubagentHooksSchema = z.union([
  z.record(z.string(), z.array(z.unknown())),
  z.array(z.unknown()),
  z.looseObject({ version: z.optional(z.string()), hooks: z.array(z.unknown()) }),
]);

const KiroCliSubagentJsonSchema = z.looseObject({
  name: z.optional(z.string()),
  description: z.optional(z.nullable(z.string())),
  prompt: z.optional(z.nullable(z.string())),
  tools: z.optional(z.nullable(z.array(z.string()))),
  toolAliases: z.optional(z.nullable(z.record(z.string(), z.string()))),
  toolSettings: z.optional(z.nullable(z.unknown())),
  toolSchema: z.optional(z.nullable(z.unknown())),
  hooks: z.optional(z.nullable(KiroCliSubagentHooksSchema)),
  model: z.optional(z.nullable(z.string())),
  mcpServers: z.optional(z.nullable(z.record(z.string(), z.unknown()))),
  useLegacyMcpJson: z.optional(z.nullable(z.boolean())),
  resources: z.optional(z.nullable(z.array(z.string()))),
  allowedTools: z.optional(z.nullable(z.array(z.string()))),
  includeMcpJson: z.optional(z.nullable(z.boolean())),
});

type KiroCliSubagentJson = z.infer<typeof KiroCliSubagentJsonSchema>;

export type KiroSubagentParams = {
  body: string;
} & AiFileParams;

export class KiroSubagent extends ToolSubagent {
  private readonly body: string;

  constructor({ body, ...rest }: KiroSubagentParams) {
    if (rest.validate !== false) {
      try {
        const parsed = JSON.parse(body);
        KiroCliSubagentJsonSchema.parse(parsed);
      } catch (error) {
        throw new Error(
          `Invalid JSON in ${join(rest.relativeDirPath, rest.relativeFilePath)}: ${
            error instanceof Error ? error.message : String(error)
          }`,
          { cause: error },
        );
      }
    }

    super({
      ...rest,
    });

    this.body = body;
  }

  // Kiro reads agent configs from `.kiro/agents/` (workspace) and, for the
  // Kiro CLI, also from `~/.kiro/agents/` (global, local takes precedence).
  // Both scopes share the same relative path; the home-directory root is
  // applied by the generate pipeline in global mode.
  // https://kiro.dev/docs/cli/custom-agents/configuration-reference/
  static getSettablePaths(_options: { global?: boolean } = {}): ToolSubagentSettablePaths {
    return {
      relativeDirPath: KIRO_AGENTS_DIR_PATH,
    };
  }

  getBody(): string {
    return this.body;
  }

  protected static getToolTarget(): "kiro" | "kiro-cli" {
    return "kiro";
  }

  toRulesyncSubagent(): RulesyncSubagent {
    let parsed: KiroCliSubagentJson;
    try {
      parsed = JSON.parse(this.body);
    } catch (error) {
      throw new Error(
        `Failed to parse JSON in ${join(this.getRelativeDirPath(), this.getRelativeFilePath())}: ${
          error instanceof Error ? error.message : String(error)
        }`,
        { cause: error },
      );
    }
    const { name, description, prompt, ...restFields } = parsed;
    const toolTarget = (this.constructor as typeof KiroSubagent).getToolTarget();

    // Build kiro section with all fields except name, description, and prompt
    const kiroSection: Record<string, unknown> = {
      ...restFields,
    };

    const rulesyncFrontmatter: RulesyncSubagentFrontmatter = {
      targets: [toolTarget],
      name: name ?? basename(this.getRelativeFilePath(), ".json"),
      description: description ?? undefined,
      // Only include kiro section if there are fields
      ...(Object.keys(kiroSection).length > 0 && { kiro: kiroSection }),
    };

    return new RulesyncSubagent({
      outputRoot: ".",
      frontmatter: rulesyncFrontmatter,
      body: prompt ?? "",
      relativeDirPath: RULESYNC_SUBAGENTS_RELATIVE_DIR_PATH,
      relativeFilePath: this.getRelativeFilePath().replace(/\.json$/, ".md"),
      validate: true,
    });
  }

  static fromRulesyncSubagent({
    outputRoot = process.cwd(),
    rulesyncSubagent,
    validate = true,
    global = false,
  }: ToolSubagentFromRulesyncSubagentParams): ToolSubagent {
    const frontmatter = rulesyncSubagent.getFrontmatter();
    const rawSection: Record<string, unknown> = frontmatter.kiro ?? {};
    const kiroSection = this.filterToolSpecificSection(rawSection, [
      "name",
      "description",
      "prompt",
    ]);

    // Build kiro JSON from rulesync frontmatter + kiro section (tool-specific fields only)
    const json: KiroCliSubagentJson = {
      name: frontmatter.name,
      description: frontmatter.description || null,
      prompt: rulesyncSubagent.getBody() || null,
      ...kiroSection,
    };

    const body = JSON.stringify(json, null, 2);
    const paths = this.getSettablePaths({ global });
    const relativeFilePath = rulesyncSubagent.getRelativeFilePath().replace(/\.md$/, ".json");

    return new this({
      outputRoot,
      body,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath,
      fileContent: body,
      validate,
      global,
    });
  }

  validate(): ValidationResult {
    try {
      const parsed = JSON.parse(this.body);
      KiroCliSubagentJsonSchema.parse(parsed);
      return { success: true, error: null };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error : new Error(String(error)),
      };
    }
  }

  static isTargetedByRulesyncSubagent(rulesyncSubagent: RulesyncSubagent): boolean {
    return this.isTargetedByRulesyncSubagentDefault({
      rulesyncSubagent,
      toolTarget: this.getToolTarget(),
    });
  }

  static async fromFile({
    outputRoot = process.cwd(),
    relativeFilePath,
    validate = true,
    global = false,
  }: ToolSubagentFromFileParams): Promise<KiroSubagent> {
    const paths = this.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, relativeFilePath);
    const fileContent = await readFileContent(filePath);

    const subagent = new this({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath,
      body: fileContent.trim(),
      fileContent,
      validate,
      global,
    });

    if (validate) {
      const result = subagent.validate();
      if (!result.success) {
        throw new Error(
          `Invalid JSON in ${filePath}: ${result.error instanceof Error ? result.error.message : String(result.error)}`,
        );
      }
    }

    return subagent;
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    relativeFilePath,
  }: ToolSubagentForDeletionParams): KiroSubagent {
    return new this({
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      body: "",
      fileContent: "",
      validate: false,
    });
  }
}
