// Grok stores the coarse permission toggle as `[ui] permission_mode` in
// config.toml (kept as a backward-compatible fallback) and the fine-grained
// rules as Claude-style entries under the `[permission]` allow/deny/ask arrays.
// https://docs.x.ai/build/settings/reference
// https://docs.x.ai/build/modes-and-commands
const GROKCLI_UI_KEY = "ui";
const GROKCLI_PERMISSION_MODE_KEY = "permission_mode";
const GROKCLI_PERMISSION_KEY = "permission";

type GrokPermissionMode = "ask" | "always-approve";

// Grok's third mode: classifier-based approval, toggled in the TUI with
// `/auto`. Nothing in the canonical permissions model derives it, so rulesync
// never writes it — but it is preserved when a config already selects it.
// https://docs.x.ai/build/features/permissions
const GROKCLI_AUTO_PERMISSION_MODE = "auto";

// rulesync canonical catch-all pattern (Grok's coarse mode is global, so only a
// catch-all maps cleanly back on import from `permission_mode`).
const CATCH_ALL_PATTERN = "*";

const MCP_CANONICAL_PREFIX = "mcp__";

// Canonical category ⇒ Grok Claude-style tool prefix. Grok exposes no separate
// `Write` tool (writes gate through `Edit`), so `write` collapses onto `Edit`;
// `Glob` is an accepted alias onto the same filter as `Grep` (upstream
// `tool_name_to_filter`: `"Grep" | "Glob" => Some(ToolFilter::Grep)`), so it
// is emitted under its own spelling and enforced like a `Grep` rule. `agent`
// maps onto `AgentMessage`, the nearest named filter (added in Grok 1.0.10),
// which gates only messages sent to an already-running subagent — not the
// launch of one, which upstream `AccessKind::from` checks as an `Edit` access
// on an internal `task:<subagent_type>` key we deliberately do not target.
// Its pattern tests the *target subagent id* (glob or prefix), not the
// subagent type a Claude Code `Agent(...)` rule names, so a canonical `agent`
// rule controls steering messages to Grok subagents, never their start. The
// only category
// with no Grok tool at all is `notebookedit`, which is skipped. MCP categories
// are handled separately (see `buildGrokEntry`).
// https://github.com/xai-org/grok-build/blob/main/crates/codegen/xai-grok-workspace/src/permission/rules.rs
const CATEGORY_TO_GROK_TOOL: Record<string, string> = {
  bash: "Bash",
  read: "Read",
  edit: "Edit",
  write: "Edit",
  grep: "Grep",
  glob: "Glob",
  webfetch: "WebFetch",
  websearch: "WebSearch",
  agent: "AgentMessage",
};

// Grok's legacy spellings of the `AgentMessage` filter. Upstream still parses
// them so already-persisted policies keep loading; rulesync reads them on
// import but always emits the canonical `AgentMessage`.
const GROK_LEGACY_AGENT_MESSAGE_TOOLS = ["SendSubagentMessage", "SendAgentMessage"] as const;

// Grok tool prefix ⇒ canonical category (inverse of the above; `write` is not
// recovered because it collapses onto `Edit` on export — a documented lossy
// mapping). `Grep` and `Glob` share one Grok filter but are kept apart here so
// each spelling round-trips to the category it was authored under. `MCPTool`
// is handled separately in `parseGrokEntry`.
const GROK_TOOL_TO_CATEGORY: Record<string, string> = {
  Bash: "bash",
  Read: "read",
  Edit: "edit",
  Grep: "grep",
  Glob: "glob",
  WebFetch: "webfetch",
  WebSearch: "websearch",
  AgentMessage: "agent",
  ...Object.fromEntries(GROK_LEGACY_AGENT_MESSAGE_TOOLS.map((tool) => [tool, "agent"])),
};

const GROK_MCP_TOOL = "MCPTool";

// Lowercased view of the tool tables above, used to resolve the `tool` field of
// a verbose `[[permission.rules]]` entry. The settings reference spells the two
// forms differently — the verbose `tool` field takes
// `any | bash | edit | read | grep | mcp | webfetch` (lowercase) while the
// compact array entries are capitalized (`Bash(git *)`, `MCPTool(server__*)`) —
// so the verbose lookup is case-insensitive and accepts both spellings.
// The verbose form spells the agent filter `agent_message` (serde rename on
// upstream `ToolFilter`, with the lowercased compact name as an accepted alias), so that
// underscore spelling is added on top of the lowercased compact names.
const GROK_TOOL_TO_CATEGORY_LOWER: Record<string, string> = {
  ...Object.fromEntries(
    Object.entries(GROK_TOOL_TO_CATEGORY).map(([tool, category]) => [tool.toLowerCase(), category]),
  ),
  agent_message: "agent",
};

// Both spellings of Grok's MCP tool: `mcp` is the documented verbose value,
// and the lowercased compact name (`MCPTool`) is accepted for symmetry.
const GROK_MCP_TOOL_ALIASES: ReadonlySet<string> = new Set(["mcp", GROK_MCP_TOOL.toLowerCase()]);

// Key of the verbose rule form inside `[permission]`.
const GROKCLI_PERMISSION_RULES_KEY = "rules";

/**
 * Build a Grok Claude-style permission entry (e.g. `Bash(git *)`, `Read`,
 * `MCPTool(server__tool)`) from a canonical category + pattern. Returns `null`
 * for categories Grok cannot express so callers can skip them.
 *
 * Scoped MCP categories (`mcp__<remainder>`) fold their address into the
 * parentheses (`MCPTool(<remainder>)`); the bare `mcp` category becomes
 * `MCPTool`. For every other tool, a `*` pattern emits the bare tool name and a
 * concrete pattern emits `Tool(pattern)`.
 */
function buildGrokEntry(category: string, pattern: string): string | null {
  if (category.startsWith(MCP_CANONICAL_PREFIX)) {
    const remainder = category.slice(MCP_CANONICAL_PREFIX.length);
    return remainder.length > 0 ? `${GROK_MCP_TOOL}(${remainder})` : GROK_MCP_TOOL;
  }
  if (category === "mcp") {
    return pattern === CATCH_ALL_PATTERN || pattern === ""
      ? GROK_MCP_TOOL
      : `${GROK_MCP_TOOL}(${pattern})`;
  }
  const tool = CATEGORY_TO_GROK_TOOL[category];
  if (tool === undefined) {
    return null;
  }
  return pattern === CATCH_ALL_PATTERN || pattern === "" ? tool : `${tool}(${pattern})`;
}

/**
 * Parse a Grok Claude-style permission entry back into a canonical category +
 * pattern. Entries without parentheses are treated as catch-all (`*`). Returns
 * `null` for tool prefixes with no canonical equivalent (e.g. `any`).
 */
function parseGrokEntry(entry: string): { category: string; pattern: string } | null {
  const trimmed = entry.trim();
  const parenIndex = trimmed.indexOf("(");
  let tool: string;
  let inner: string;
  if (parenIndex === -1 || !trimmed.endsWith(")")) {
    tool = trimmed;
    inner = "";
  } else {
    tool = trimmed.slice(0, parenIndex);
    inner = trimmed.slice(parenIndex + 1, -1).trim();
  }

  if (parenIndex === -1 && tool.startsWith(MCP_CANONICAL_PREFIX)) {
    return parseClaudeStyleMcpEntry(tool);
  }

  if (tool === GROK_MCP_TOOL) {
    return inner.length > 0
      ? { category: `${MCP_CANONICAL_PREFIX}${inner}`, pattern: CATCH_ALL_PATTERN }
      : { category: "mcp", pattern: CATCH_ALL_PATTERN };
  }

  const category = GROK_TOOL_TO_CATEGORY[tool];
  if (category === undefined) {
    return null;
  }
  return { category, pattern: inner.length > 0 ? inner : CATCH_ALL_PATTERN };
}

/**
 * Parse the `.claude/settings.json` spelling `mcp__<server>[__<tool>]` that
 * Grok also accepts in the compact arrays (paren-less only). Grok strips the
 * `mcp__` prefix and matches the rest against its `<server>__<tool>` names:
 * `mcp__*` covers every MCP tool, a server-only `mcp__github` becomes
 * `github__*`, and `mcp__github__get_issue` stays exact — the same
 * canonical categories `MCPTool`, `MCPTool(github__*)` and
 * `MCPTool(github__get_issue)` import to. A bare `mcp__` matches nothing
 * upstream, so it has no canonical equivalent.
 * https://github.com/xai-org/grok-build/blob/main/crates/codegen/xai-grok-permission-rules/src/rules.rs
 */
function parseClaudeStyleMcpEntry(entry: string): { category: string; pattern: string } | null {
  const rest = entry.slice(MCP_CANONICAL_PREFIX.length);
  if (rest.length === 0) {
    return null;
  }
  if (rest === CATCH_ALL_PATTERN) {
    return { category: "mcp", pattern: CATCH_ALL_PATTERN };
  }
  const address = rest.includes("__") ? rest : `${rest}__*`;
  return { category: `${MCP_CANONICAL_PREFIX}${address}`, pattern: CATCH_ALL_PATTERN };
}

/**
 * Parse one entry of the verbose `[[permission.rules]]` form
 * (`{ action = "allow", tool = "bash", pattern = "git *" }`) into a canonical
 * category + pattern + action. Unlike the compact array entries these are TOML
 * tables, so the tool name arrives as its own field instead of an entry string.
 * Returns `null` for malformed entries and for tools with no canonical
 * equivalent, so callers can skip them (the whole `rules` array is preserved
 * verbatim on generate regardless).
 */
function parseGrokRule(
  rule: unknown,
): { category: string; pattern: string; action: PermissionAction } | null {
  if (!isRecord(rule)) {
    return null;
  }
  const { action: rawAction, tool, pattern } = rule;
  const parsedAction = PermissionActionSchema.safeParse(rawAction);
  if (!parsedAction.success) {
    return null;
  }
  const action = parsedAction.data;
  if (typeof tool !== "string") {
    return null;
  }
  if (pattern !== undefined && typeof pattern !== "string") {
    return null;
  }
  const trimmedPattern = pattern?.trim() ?? "";
  const resolvedPattern = trimmedPattern.length > 0 ? trimmedPattern : CATCH_ALL_PATTERN;

  const lowerTool = tool.trim().toLowerCase();
  if (GROK_MCP_TOOL_ALIASES.has(lowerTool)) {
    // Mirrors `parseGrokEntry`: an MCP address folds into the category so the
    // canonical side keeps the scoped `mcp__<address>` shape.
    return resolvedPattern === CATCH_ALL_PATTERN
      ? { category: "mcp", pattern: CATCH_ALL_PATTERN, action }
      : {
          category: `${MCP_CANONICAL_PREFIX}${resolvedPattern}`,
          pattern: CATCH_ALL_PATTERN,
          action,
        };
  }

  // `hasOwn` so a `tool` naming an inherited `Object.prototype` member
  // (`constructor`, `toString`, ...) is rejected instead of resolving to a
  // bogus category.
  if (!Object.hasOwn(GROK_TOOL_TO_CATEGORY_LOWER, lowerTool)) {
    return null;
  }
  const category = GROK_TOOL_TO_CATEGORY_LOWER[lowerTool];
  if (category === undefined) {
    return null;
  }
  return { category, pattern: resolvedPattern, action };
}

/**
 * Permissions adapter for the xAI Grok Build CLI (`grokcli`).
 *
 * Grok Build CLI ships a Claude-style rule system under `[permission]` in
 * `~/.grok/config.toml`: `allow` / `deny` / `ask` arrays of entries such as
 * `Bash(git *)`, `Read(src/**)`, `Edit`, `Grep`, `MCPTool(server__tool)`,
 * `WebFetch`, and `WebSearch`, evaluated with precedence `deny > ask > allow`
 * (https://docs.x.ai/build/settings/reference). rulesync's canonical
 * per-category, per-pattern model maps almost 1:1:
 *   - Generate: each `permission.<category>.<pattern> = allow|ask|deny` becomes
 *     the matching Grok entry and is bucketed into the `[permission]` array for
 *     that action. `bash|read|edit|grep|glob|webfetch|websearch|agent` map to
 *     their Grok tool; `write` collapses onto `Edit` (Grok has no `Write`
 *     tool); `glob` maps to `Glob` (an upstream alias of the `Grep` filter);
 *     `agent` maps to `AgentMessage` (which gates messages to a running
 *     subagent rather than its launch, and whose pattern is a subagent id
 *     rather than a subagent type); `mcp__*` maps to `MCPTool(...)` (a scoped
 *     MCP category folds its address into the parentheses, so a non-`*`
 *     argument pattern on it is not represented). The one category with no Grok tool (`notebookedit`) is
 *     skipped (with a warning when it carries a `deny` rule, to surface the
 *     gap). When two canonical rules collapse onto the same Grok
 *     entry with different actions (e.g. `edit` allow + `write` deny → `Edit`),
 *     the strictest wins (`deny > ask > allow`) and a warning is logged, so the
 *     entry never lands contradictorily in two arrays.
 *   - Import: both documented `[permission]` forms are parsed back into
 *     canonical categories — the compact `allow`/`deny`/`ask` arrays and the
 *     verbose `[[permission.rules]]` tables
 *     (`{ action = "allow", tool = "bash", pattern = "git *" }`), whose `tool`
 *     field is matched case-insensitively against the same tool table, plus
 *     the documented `mcp` alias for the compact form's `MCPTool`. Rules
 *     from the two forms are merged with the same `deny > ask > allow`
 *     precedence. When neither form carries a rule (older configs), the coarse
 *     `[ui] permission_mode` is used as a fallback. Generate always emits the
 *     compact arrays, so a user-authored `rules` array is preserved verbatim
 *     but not reconciled against them.
 *
 * The coarse `[ui] permission_mode` toggle is still written for backward
 * compatibility with older Grok versions: `always-approve` when the config is
 * pure-`allow`, otherwise `ask` (conservative — it is never `always-approve`
 * while any `deny`/`ask` rule exists, so it never contradicts the fine-grained
 * arrays). It is a user-level UI setting, so it is only written in global scope
 * (see below).
 *
 * Both scopes are supported: the adapter syncs the project-level
 * `./.grok/config.toml` (default) and the user-level `~/.grok/config.toml`
 * (with `--global`). Grok documents that "Project configs are limited to MCP
 * servers, plugins, and permission rules, not full user configs"
 * (https://docs.x.ai/build/settings), so the project config carries only the
 * fine-grained `[permission]` rules; the coarse `[ui] permission_mode` UI toggle
 * is written in global scope only. The shared config is merged in
 * place: rulesync owns the `[permission]` `allow`/`deny`/`ask` entries for the
 * tools it models and (in global scope) the `[ui] permission_mode` value, while
 * every other key
 * (e.g. `[mcp_servers]`, `[permission] rules`, `[sandbox]`) and any user-authored
 * entries for tool prefixes rulesync cannot model (e.g. `any`) are preserved.
 * The file is never deleted.
 */
export class GrokcliPermissions extends ToolPermissions {
  constructor(params: AiFileParams) {
    super({
      ...params,
      fileContent: params.fileContent ?? "",
    });
  }

  override isDeletable(): boolean {
    return false;
  }

  static getSettablePaths(_options?: { global?: boolean }): ToolPermissionsSettablePaths {
    // Both project (./.grok/config.toml) and global (~/.grok/config.toml) use
    // the same relative path; the scope is resolved by the outputRoot passed to
    // the processor (mirrors GrokcliMcp.getSettablePaths).
    return {
      relativeDirPath: GROKCLI_DIR,
      relativeFilePath: GROKCLI_CONFIG_FILE_NAME,
    };
  }

  static async fromFile({
    outputRoot = process.cwd(),
    validate = true,
    global = false,
  }: ToolPermissionsFromFileParams): Promise<GrokcliPermissions> {
    const paths = GrokcliPermissions.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    const fileContent = (await readFileContentOrNull(filePath)) ?? "";
    return new GrokcliPermissions({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent,
      validate,
      global,
    });
  }

  static async fromRulesyncPermissions({
    outputRoot = process.cwd(),
    rulesyncPermissions,
    logger,
    global = false,
  }: ToolPermissionsFromRulesyncPermissionsParams): Promise<GrokcliPermissions> {
    const paths = GrokcliPermissions.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    // Read without initializing so a dry-run/check does not create the user's
    // config.toml as a side effect (mirrors the Goose adapter).
    const existingContent = (await readFileContentOrNull(filePath)) ?? "";

    let parsed: smolToml.TomlTable;
    try {
      parsed = existingContent.trim() === "" ? {} : smolToml.parse(existingContent);
    } catch (error) {
      throw new Error(
        `Failed to parse existing Grok config.toml at ${filePath}: ${formatError(error)}`,
        { cause: error },
      );
    }

    const config = rulesyncPermissions.getJson();

    // Fine-grained `[permission]` arrays (the high-fidelity surface). rulesync
    // owns the entries for the tools it models; other `[permission]` keys (e.g.
    // verbose `rules`) and user-authored entries for tool prefixes rulesync
    // cannot model (e.g. `any`) are preserved.
    const existingPermission = isRecord(parsed[GROKCLI_PERMISSION_KEY])
      ? parsed[GROKCLI_PERMISSION_KEY]
      : {};
    const buckets = buildGrokPermissionArrays(config, existingPermission, logger);
    const permission = {
      ...existingPermission,
      allow: buckets.allow,
      deny: buckets.deny,
      ask: buckets.ask,
    };

    // Coarse `[ui] permission_mode` fallback for older Grok versions. This is a
    // user-level UI toggle, so it is only written to the global config: Grok
    // documents that project configs are limited to MCP servers, plugins, and
    // permission rules — not full user configs — so the fine-grained
    // `[permission]` arrays are the only permission surface written in project
    // scope. In global scope the `ui` key is patched alongside `permission`.
    //
    // Grok's third mode, `auto`, is left exactly as it is when the config
    // already selects it: it has no canonical counterpart to derive it from, so
    // overwriting it would silently downgrade the user to `ask` on every
    // `generate --global`.
    const existingUi = isRecord(parsed[GROKCLI_UI_KEY]) ? parsed[GROKCLI_UI_KEY] : {};
    const uiPatch =
      global && existingUi[GROKCLI_PERMISSION_MODE_KEY] !== GROKCLI_AUTO_PERMISSION_MODE
        ? {
            [GROKCLI_UI_KEY]: {
              ...existingUi,
              [GROKCLI_PERMISSION_MODE_KEY]: deriveGrokPermissionMode(config),
            },
          }
        : {};

    return new GrokcliPermissions({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent: applySharedConfigPatch({
        fileKey: sharedConfigFileKey(paths),
        feature: "permissions",
        existingContent,
        patch: { [GROKCLI_PERMISSION_KEY]: permission, ...uiPatch },
        filePath,
      }),
      validate: true,
      global,
    });
  }

  toRulesyncPermissions(): RulesyncPermissions {
    let parsed: smolToml.TomlTable;
    try {
      const content = this.getFileContent();
      parsed = content.trim() === "" ? {} : smolToml.parse(content);
    } catch (error) {
      throw new Error(
        `Failed to parse Grok config.toml content in ${join(this.getRelativeDirPath(), this.getRelativeFilePath())}: ${formatError(error)}`,
        { cause: error },
      );
    }

    const permission = isRecord(parsed[GROKCLI_PERMISSION_KEY])
      ? parsed[GROKCLI_PERMISSION_KEY]
      : {};
    const fineGrained = parseGrokPermissionArrays(permission);

    // Prefer the fine-grained `[permission]` arrays when present; fall back to
    // the coarse `[ui] permission_mode` for older configs that have neither.
    const rulesyncConfig: PermissionsConfig = fineGrained
      ? { permission: fineGrained }
      : { permission: { bash: { [CATCH_ALL_PATTERN]: legacyModeAction(parsed) } } };

    return this.toRulesyncPermissionsDefault({
      fileContent: JSON.stringify(rulesyncConfig, null, 2),
    });
  }

  validate(): ValidationResult {
    return { success: true, error: null };
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    relativeFilePath,
    global = false,
  }: ToolPermissionsForDeletionParams): GrokcliPermissions {
    return new GrokcliPermissions({
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      fileContent: "",
      validate: false,
      global,
    });
  }
}

// Grok's documented evaluation precedence, `deny > ask > allow`. Used to
// resolve the case where two canonical rules collapse onto the same Grok entry
// (e.g. `edit` and `write` both map to `Edit`): the strictest action wins, so
// only one non-contradictory entry is emitted.
const ACTION_RANK: Record<PermissionAction, number> = { allow: 0, ask: 1, deny: 2 };

/**
 * Collect user-authored entries from an existing `[permission]` array whose
 * tool prefix rulesync cannot model (e.g. `any`). Such entries are
 * preserved verbatim so replacing the arrays does not silently drop them
 * (mirrors the Cursor adapter's preservation of unmanaged types).
 */
function unmanagedEntries(existingPermission: Record<string, unknown>, key: string): string[] {
  const arr = isStringArray(existingPermission[key]) ? existingPermission[key] : [];
  return arr.filter((entry) => parseGrokEntry(entry) === null);
}

/**
 * Bucket canonical rules into Grok's `[permission]` allow/deny/ask arrays of
 * Claude-style entries, resolving collapse collisions via `deny > ask > allow`.
 * Categories Grok cannot express are skipped (with a warning when they carry a
 * `deny` rule); entries the user authored for tools rulesync cannot model are
 * preserved from `existingPermission`.
 */
function buildGrokPermissionArrays(
  config: PermissionsConfig,
  existingPermission: Record<string, unknown>,
  logger?: Logger,
): { allow: string[]; deny: string[]; ask: string[] } {
  // Map each managed entry to a single action; on collision keep the strictest
  // (and warn), so no entry ends up contradictorily in two arrays.
  const ranked = new Map<string, PermissionAction>();
  for (const [category, rules] of Object.entries(honorAllToolsOnBash(config.permission))) {
    for (const [pattern, action] of Object.entries(rules)) {
      const entry = buildGrokEntry(category, pattern);
      if (entry === null) {
        if (action === "deny" && logger) {
          logger.warn(
            `Grok CLI has no permission tool for the '${category}' category; ` +
              `its 'deny' rule could not be represented and was skipped.`,
          );
        }
        continue;
      }
      const existing = ranked.get(entry);
      if (existing !== undefined && existing !== action) {
        logger?.warn(
          `Grok permission entry '${entry}' received conflicting actions ` +
            `('${existing}' and '${action}'); keeping the stricter one (deny > ask > allow).`,
        );
      }
      if (existing === undefined || ACTION_RANK[action] > ACTION_RANK[existing]) {
        ranked.set(entry, action);
      }
    }
  }

  const allow = unmanagedEntries(existingPermission, "allow");
  const deny = unmanagedEntries(existingPermission, "deny");
  const ask = unmanagedEntries(existingPermission, "ask");
  for (const [entry, action] of ranked) {
    if (action === "allow") allow.push(entry);
    else if (action === "deny") deny.push(entry);
    else ask.push(entry);
  }

  return { allow: uniq(allow.toSorted()), deny: uniq(deny.toSorted()), ask: uniq(ask.toSorted()) };
}

/**
 * Parse Grok's `[permission]` section back into a canonical permission map,
 * reading both supported forms: the compact `allow`/`deny`/`ask` arrays of
 * Claude-style entries and the verbose `[[permission.rules]]` tables
 * (`{ action, tool, pattern }`). Returns `null` only when neither form carries
 * any rule, so the caller can fall back to the coarse `permission_mode`.
 * Precedence `deny > ask > allow` is applied across both forms, so a tool
 * described more than once resolves to the strictest action.
 */
function parseGrokPermissionArrays(
  permission: Record<string, unknown>,
): Record<string, Record<string, PermissionAction>> | null {
  const allow = isStringArray(permission.allow) ? permission.allow : undefined;
  const deny = isStringArray(permission.deny) ? permission.deny : undefined;
  const ask = isStringArray(permission.ask) ? permission.ask : undefined;
  const rules = Array.isArray(permission[GROKCLI_PERMISSION_RULES_KEY])
    ? permission[GROKCLI_PERMISSION_RULES_KEY]
    : undefined;
  // Treat absent *and* all-empty forms as "no fine-grained rules" so the
  // coarse `permission_mode` fallback still applies (a freshly generated
  // empty config writes empty arrays alongside the mode). A non-empty `rules`
  // array counts even if none of its entries turn out to be parseable, so a
  // verbose-form config is never mistaken for a config with no rules at all.
  const total =
    (allow?.length ?? 0) + (deny?.length ?? 0) + (ask?.length ?? 0) + (rules?.length ?? 0);
  if (total === 0) {
    return null;
  }

  const result: Record<string, Record<string, PermissionAction>> = {};
  const record = ({
    category,
    pattern,
    action,
  }: {
    category: string;
    pattern: string;
    action: PermissionAction;
  }) => {
    const bucket = (result[category] ??= {});
    const existing = bucket[pattern];
    // Strictest wins across both forms (deny > ask > allow), independent of the
    // order the two sources are read in.
    if (existing === undefined || ACTION_RANK[action] > ACTION_RANK[existing]) {
      bucket[pattern] = action;
    }
  };

  const applyEntries = (entries: string[] | undefined, action: PermissionAction) => {
    for (const entry of entries ?? []) {
      const parsed = parseGrokEntry(entry);
      if (parsed === null) continue;
      record({ ...parsed, action });
    }
  };
  applyEntries(allow, "allow");
  applyEntries(ask, "ask");
  applyEntries(deny, "deny");

  for (const rule of rules ?? []) {
    const parsed = parseGrokRule(rule);
    if (parsed === null) continue;
    record(parsed);
  }

  return result;
}

/**
 * Legacy coarse fallback: map `[ui] permission_mode` to a canonical action.
 * `always-approve` ⇒ `allow`; anything else (including a missing mode) ⇒ `ask`.
 */
function legacyModeAction(parsed: smolToml.TomlTable): PermissionAction {
  const ui = isRecord(parsed[GROKCLI_UI_KEY]) ? parsed[GROKCLI_UI_KEY] : {};
  return ui[GROKCLI_PERMISSION_MODE_KEY] === "always-approve" ? "allow" : "ask";
}

/**
 * Collapse a rulesync permissions config into Grok's single coarse mode.
 * Any `deny`/`ask` rule anywhere keeps prompting (`ask`); otherwise an existing
 * `allow` rule opts into `always-approve`; an empty config defaults to `ask`.
 */
function deriveGrokPermissionMode(config: PermissionsConfig): GrokPermissionMode {
  let hasAllow = false;

  for (const rules of Object.values(config.permission)) {
    for (const action of Object.values(rules)) {
      if (action === "deny" || action === "ask") {
        return "ask";
      }
      if (action === "allow") {
        hasAllow = true;
      }
    }
  }

  return hasAllow ? "always-approve" : "ask";
}
