import { join } from "node:path";

import { z } from "zod/mini";

import {
  DEVIN_GLOBAL_SKILLS_DIR_PATH,
  DEVIN_SKILLS_DIR_PATH,
} from "../../constants/devin-paths.js";
import { SKILL_FILE_NAME } from "../../constants/general.js";
import { RULESYNC_SKILLS_RELATIVE_DIR_PATH } from "../../constants/rulesync-paths.js";
import { ValidationResult } from "../../types/ai-dir.js";
import { formatError } from "../../utils/error.js";
import { rulesyncCommandSlugExists } from "../commands/command-skill-ownership.js";
import { RulesyncSkill, RulesyncSkillFrontmatterInput, SkillFile } from "./rulesync-skill.js";
import {
  ToolSkill,
  ToolSkillForDeletionParams,
  ToolSkillFromDirParams,
  ToolSkillFromRulesyncSkillParams,
  ToolSkillSettablePaths,
} from "./tool-skill.js";

/**
 * The SKILL.md frontmatter fields Devin documents beyond name/description:
 * `argument-hint`, `model`, `subagent`, `agent`, `allowed-tools`,
 * `permissions` (load-bearing for auto-approvals since CLI v3000.1.23 /
 * Desktop v3.4.22), and `triggers` (`user` / `model` invocation gating).
 * @see https://docs.devin.ai/cli/extensibility/skills/creating-skills
 */
const DevinSkillFrontmatterSchema = z.looseObject({
  name: z.string(),
  description: z.string(),
  "argument-hint": z.optional(z.string()),
  model: z.optional(z.string()),
  subagent: z.optional(z.union([z.string(), z.boolean()])),
  agent: z.optional(z.string()),
  "allowed-tools": z.optional(z.union([z.string(), z.array(z.string())])),
  permissions: z.optional(z.record(z.string(), z.unknown())),
  triggers: z.optional(z.array(z.enum(["user", "model"]))),
});

/** The `devin` tool section of the canonical skill frontmatter. */
type DevinRulesyncSection = {
  "argument-hint"?: string;
  model?: string;
  subagent?: string | boolean;
  agent?: string;
  "allowed-tools"?: string | string[];
  permissions?: Record<string, unknown>;
  triggers?: ("user" | "model")[];
};

const DEVIN_SECTION_KEYS = [
  "argument-hint",
  "model",
  "subagent",
  "agent",
  "allowed-tools",
  "permissions",
  "triggers",
] as const;

/**
 * Resolve Devin's `triggers` from the canonical invocation flags when the
 * section does not state it outright: `disable-model-invocation: true` leaves
 * only the `user` trigger, `user-invocable: false` only the `model` trigger.
 * With neither flag set, `triggers` is omitted (Devin's default is both).
 */
function resolveDevinTriggers({
  section,
  disableModelInvocation,
  userInvocable,
}: {
  section: DevinRulesyncSection | undefined;
  disableModelInvocation: boolean | undefined;
  userInvocable: boolean | undefined;
}): ("user" | "model")[] | undefined {
  if (section?.triggers !== undefined) {
    return section.triggers;
  }
  if (disableModelInvocation === true && userInvocable === false) {
    return [];
  }
  if (disableModelInvocation === true) {
    return ["user"];
  }
  if (userInvocable === false) {
    return ["model"];
  }
  return undefined;
}

export type DevinSkillFrontmatter = z.infer<typeof DevinSkillFrontmatterSchema>;

export type DevinSkillParams = {
  outputRoot?: string;
  relativeDirPath?: string;
  dirName: string;
  frontmatter: DevinSkillFrontmatter;
  body: string;
  otherFiles?: SkillFile[];
  validate?: boolean;
  global?: boolean;
};

/**
 * Represents a Devin (now Devin Desktop) skill directory.
 * Devin supports skills in both project mode under .devin/skills/
 * (preferred since the Devin Desktop rebrand; .devin/skills/ is the legacy
 * fallback the tool still reads) and global mode under the Devin-native
 * ~/.config/devin/skills/ (consistent with Devin's global agents/rules paths;
 * the legacy channel-dependent ~/.codeium/<channel>/skills/ is no longer emitted).
 */
export class DevinSkill extends ToolSkill {
  constructor({
    outputRoot = process.cwd(),
    relativeDirPath = DevinSkill.getSettablePaths().relativeDirPath,
    dirName,
    frontmatter,
    body,
    otherFiles = [],
    validate = true,
    global = false,
  }: DevinSkillParams) {
    super({
      outputRoot,
      relativeDirPath,
      dirName,
      mainFile: {
        name: SKILL_FILE_NAME,
        body,
        frontmatter: { ...frontmatter },
      },
      otherFiles,
      global,
    });

    if (validate) {
      const result = this.validate();
      if (!result.success) {
        throw result.error;
      }
    }
  }

  static getSettablePaths({ global = false }: { global?: boolean } = {}): ToolSkillSettablePaths {
    // Devin skills use different paths for project and global modes:
    // - Project mode: {process.cwd()}/.devin/skills/ (preferred since the Devin
    //   Desktop rebrand; .devin/skills/ is the legacy fallback)
    // - Global mode: {getHomeDirectory()}/.config/devin/skills/ (Devin-native)
    if (global) {
      return {
        relativeDirPath: DEVIN_GLOBAL_SKILLS_DIR_PATH,
      };
    }
    return {
      relativeDirPath: DEVIN_SKILLS_DIR_PATH,
    };
  }

  getFrontmatter(): DevinSkillFrontmatter {
    const result = DevinSkillFrontmatterSchema.parse(this.requireMainFileFrontmatter());
    return result;
  }

  getBody(): string {
    return this.mainFile?.body ?? "";
  }

  validate(): ValidationResult {
    if (!this.mainFile) {
      return {
        success: false,
        error: new Error(`${this.getDirPath()}: ${SKILL_FILE_NAME} file does not exist`),
      };
    }

    const result = DevinSkillFrontmatterSchema.safeParse(this.mainFile.frontmatter);
    if (!result.success) {
      return {
        success: false,
        error: new Error(
          `Invalid frontmatter in ${this.getDirPath()}: ${formatError(result.error)}`,
        ),
      };
    }

    return { success: true, error: null };
  }

  toRulesyncSkill(): RulesyncSkill {
    const frontmatter = this.getFrontmatter();
    const devinSection: DevinRulesyncSection = {};
    for (const key of DEVIN_SECTION_KEYS) {
      const value = frontmatter[key];
      if (value !== undefined) {
        (devinSection as Record<string, unknown>)[key] = value;
      }
    }
    const rulesyncFrontmatter: RulesyncSkillFrontmatterInput = {
      name: frontmatter.name,
      description: frontmatter.description,
      targets: ["*"],
      ...(Object.keys(devinSection).length > 0 && { devin: devinSection }),
    };

    return new RulesyncSkill({
      outputRoot: this.outputRoot,
      relativeDirPath: RULESYNC_SKILLS_RELATIVE_DIR_PATH,
      dirName: this.getDirName(),
      frontmatter: rulesyncFrontmatter,
      body: this.getBody(),
      otherFiles: this.getOtherFiles(),
      validate: true,
      global: this.global,
    });
  }

  static fromRulesyncSkill({
    outputRoot = process.cwd(),
    rulesyncSkill,
    validate = true,
    global = false,
  }: ToolSkillFromRulesyncSkillParams): DevinSkill {
    const settablePaths = this.getSettablePaths({ global });
    const rulesyncFrontmatter = rulesyncSkill.getFrontmatter();
    const devinSection = (rulesyncFrontmatter as { devin?: DevinRulesyncSection }).devin;
    const triggers = resolveDevinTriggers({
      section: devinSection,
      disableModelInvocation: rulesyncFrontmatter["disable-model-invocation"],
      userInvocable: rulesyncFrontmatter["user-invocable"],
    });

    const devinFrontmatter: DevinSkillFrontmatter = {
      name: rulesyncFrontmatter.name,
      description: rulesyncFrontmatter.description,
      ...(devinSection?.["argument-hint"] !== undefined && {
        "argument-hint": devinSection["argument-hint"],
      }),
      ...(devinSection?.model !== undefined && { model: devinSection.model }),
      ...(devinSection?.subagent !== undefined && { subagent: devinSection.subagent }),
      ...(devinSection?.agent !== undefined && { agent: devinSection.agent }),
      ...(devinSection?.["allowed-tools"] !== undefined && {
        "allowed-tools": devinSection["allowed-tools"],
      }),
      ...(devinSection?.permissions !== undefined && { permissions: devinSection.permissions }),
      ...(triggers !== undefined && { triggers }),
    };

    return new this({
      outputRoot,
      relativeDirPath: settablePaths.relativeDirPath,
      dirName: rulesyncSkill.getDirName(),
      frontmatter: devinFrontmatter,
      body: rulesyncSkill.getBody(),
      otherFiles: rulesyncSkill.getOtherFiles(),
      validate,
      global,
    });
  }

  static isTargetedByRulesyncSkill(rulesyncSkill: RulesyncSkill): boolean {
    const targets = rulesyncSkill.getFrontmatter().targets;
    return targets.includes("*") || targets.includes("devin");
  }

  /**
   * Commands are emitted into this same skills tree as `<slug>/SKILL.md`
   * (see `DevinCommand`), so a directory matching a current rulesync command
   * slug is owned by the commands feature: it must not be imported as a
   * skill nor deleted as an orphan skill.
   */
  static async isDirOwned({
    dirName,
    inputRoots,
  }: {
    outputRoot: string;
    relativeDirPath: string;
    dirName: string;
    inputRoots: readonly string[];
  }): Promise<boolean> {
    return !(await rulesyncCommandSlugExists({ inputRoots, dirName }));
  }

  static async fromDir(params: ToolSkillFromDirParams): Promise<DevinSkill> {
    const loaded = await this.loadSkillDirContent({
      ...params,
      getSettablePaths: (options) => this.getSettablePaths(options),
    });

    const result = DevinSkillFrontmatterSchema.safeParse(loaded.frontmatter);
    if (!result.success) {
      const skillDirPath = join(loaded.outputRoot, loaded.relativeDirPath, loaded.dirName);
      throw new Error(
        `Invalid frontmatter in ${join(skillDirPath, SKILL_FILE_NAME)}: ${formatError(result.error)}`,
      );
    }

    return new this({
      outputRoot: loaded.outputRoot,
      relativeDirPath: loaded.relativeDirPath,
      dirName: loaded.dirName,
      frontmatter: result.data,
      body: loaded.body,
      otherFiles: loaded.otherFiles,
      validate: true,
      global: loaded.global,
    });
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    dirName,
    global = false,
  }: ToolSkillForDeletionParams): DevinSkill {
    const settablePaths = this.getSettablePaths({ global });
    return new this({
      outputRoot,
      relativeDirPath: relativeDirPath ?? settablePaths.relativeDirPath,
      dirName,
      frontmatter: { name: "", description: "" },
      body: "",
      otherFiles: [],
      validate: false,
      global,
    });
  }
}
