import { join } from "node:path";

import * as smolToml from "smol-toml";

import { ValidationResult } from "../../types/ai-file.js";
import type { McpServer, McpServers } from "../../types/mcp.js";
import { formatError } from "../../utils/error.js";
import { readFileContentOrNull } from "../../utils/file.js";
import {
  applySharedConfigPatch,
  parseSharedConfig,
  sharedConfigFileKey,
} from "../shared/shared-config-gateway.js";
import { RulesyncMcp } from "./rulesync-mcp.js";
import {
  ToolMcp,
  ToolMcpForDeletionParams,
  ToolMcpFromFileParams,
  ToolMcpFromRulesyncMcpParams,
  ToolMcpParams,
  ToolMcpSettablePaths,
} from "./tool-mcp.js";

type VibeConfig = Record<string, unknown> & {
  mcp_servers?: VibeMcpServer[];
};

type VibeMcpServer = Record<string, unknown> & {
  name: string;
  transport?: string;
};

const VIBE_MCP_SERVER_FIELDS = [
  "transport",
  "url",
  "headers",
  "api_key_env",
  "api_key_header",
  "api_key_format",
  "command",
  "args",
  "env",
  "cwd",
  "auth",
  "startup_timeout_sec",
  "tool_timeout_sec",
  // Vibe's `/mcp` panel persists these into `config.toml` when a user toggles a
  // server or one of its tools. `disabled` matches the canonical field name;
  // `disabled_tools` is handled separately because canonical spells it
  // `disabledTools`, and `prompt` / `sampling_enabled` have no canonical
  // equivalent so they pass through as-is.
  "prompt",
  "sampling_enabled",
  "disabled",
] as const;

/**
 * Per-server keys a user sets through Vibe's `/mcp` panel rather than through
 * rulesync. `mcp_servers` is replaced as a whole array on each generate, so an
 * entry rulesync writes is seeded from the on-disk server of the same name
 * unless the rulesync source states the value itself.
 */
const VIBE_MCP_USER_MANAGED_FIELDS = [
  "prompt",
  "sampling_enabled",
  "disabled",
  "disabled_tools",
] as const;

// Legacy top-level static-auth keys. Vibe auto-promotes these into an `[auth]`
// block, but mixing them with an explicit `auth` table raises an error upstream,
// so they are suppressed whenever a structured `auth` block is present.
const VIBE_LEGACY_STATIC_AUTH_FIELDS = [
  "headers",
  "api_key_env",
  "api_key_header",
  "api_key_format",
] as const;

export class VibeMcp extends ToolMcp {
  private readonly toml: VibeConfig;

  constructor(params: ToolMcpParams) {
    super(params);
    this.toml = parseVibeConfig(this.fileContent);
  }

  getToml(): VibeConfig {
    return this.toml;
  }

  override isDeletable(): boolean {
    return false;
  }

  static getSettablePaths(_options: { global?: boolean } = {}): ToolMcpSettablePaths {
    return {
      relativeDirPath: ".vibe",
      relativeFilePath: "config.toml",
    };
  }

  static async fromFile({
    outputRoot = process.cwd(),
    validate = true,
    global = false,
  }: ToolMcpFromFileParams): Promise<VibeMcp> {
    const paths = this.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    const fileContent = (await readFileContentOrNull(filePath)) ?? smolToml.stringify({});
    const config = parseVibeConfig(fileContent);
    config.mcp_servers = normalizeMcpServersArray(config.mcp_servers);

    return new VibeMcp({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent: smolToml.stringify(config),
      validate,
      global,
    });
  }

  static async fromRulesyncMcp({
    outputRoot = process.cwd(),
    rulesyncMcp,
    validate = true,
    global = false,
  }: ToolMcpFromRulesyncMcpParams): Promise<VibeMcp> {
    const paths = this.getSettablePaths({ global });
    const filePath = join(outputRoot, paths.relativeDirPath, paths.relativeFilePath);
    const existingContent = (await readFileContentOrNull(filePath)) ?? "";
    // Through the gateway rather than `parseVibeConfig`, so a malformed file
    // reports the same message this write path produces a few lines later
    // instead of smol-toml's bare one, which names no file.
    const existingServers = normalizeMcpServersArray(
      parseSharedConfig({ format: "toml", fileContent: existingContent, filePath }).mcp_servers,
    );
    const existingByName = new Map(existingServers.map((server) => [server.name, server]));

    const rulesyncServers = rulesyncMcp.getMcpServers();
    const managedNames = new Set(Object.keys(rulesyncServers));
    const mcpServers = Object.entries(rulesyncServers).map(([name, server]) =>
      rulesyncMcpServerToVibe(name, server, existingByName.get(name)),
    );

    // Servers added outside rulesync — most importantly through `vibe mcp add`
    // (v2.23.0) and the `/mcp add` panel, which persist straight into this
    // TOML — are preserved after the managed entries instead of being deleted
    // by the whole-array replace. The flip side is documented: removing a
    // server from `.rulesync/mcp.jsonc` no longer removes it from
    // `config.toml`; delete it there (or via `vibe mcp remove`) as well.
    const unmanagedServers = existingServers.filter((server) => !managedNames.has(server.name));

    return new VibeMcp({
      outputRoot,
      relativeDirPath: paths.relativeDirPath,
      relativeFilePath: paths.relativeFilePath,
      fileContent: applySharedConfigPatch({
        fileKey: sharedConfigFileKey(paths),
        feature: "mcp",
        existingContent,
        patch: { mcp_servers: [...mcpServers, ...unmanagedServers] },
        filePath,
      }),
      validate,
      global,
    });
  }

  toRulesyncMcp(): RulesyncMcp {
    const mcpServers: McpServers = Object.fromEntries(
      normalizeMcpServersArray(this.toml.mcp_servers).map((server) => [
        server.name,
        vibeMcpServerToRulesync(server),
      ]),
    );

    return this.toRulesyncMcpDefault({
      fileContent: JSON.stringify({ mcpServers }, null, 2),
    });
  }

  validate(): ValidationResult {
    try {
      parseVibeConfig(this.fileContent);
      return { success: true, error: null };
    } catch (error) {
      return {
        success: false,
        error: new Error(`Failed to parse Vibe config TOML: ${formatError(error)}`),
      };
    }
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    relativeFilePath,
    global = false,
  }: ToolMcpForDeletionParams): VibeMcp {
    return new VibeMcp({
      outputRoot,
      relativeDirPath,
      relativeFilePath,
      fileContent: smolToml.stringify({}),
      validate: false,
      global,
    });
  }
}

function parseVibeConfig(fileContent: string): VibeConfig {
  const parsed = smolToml.parse(fileContent || smolToml.stringify({}));
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return {};
  }
  return { ...(parsed as Record<string, unknown>) };
}

function normalizeMcpServersArray(value: unknown): VibeMcpServer[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value
    .filter((entry): entry is Record<string, unknown> => {
      return entry !== null && typeof entry === "object" && !Array.isArray(entry);
    })
    .filter((entry): entry is VibeMcpServer => typeof entry.name === "string");
}

function rulesyncMcpServerToVibe(
  name: string,
  server: McpServer,
  existing?: VibeMcpServer,
): VibeMcpServer {
  const serverRecord = server as Record<string, unknown>;
  const transport = resolveVibeTransport(server);
  const vibeServer: VibeMcpServer = {
    name,
    ...(transport !== undefined && { transport }),
  };

  if (server.command !== undefined) {
    if (Array.isArray(server.command)) {
      const [command, ...commandArgs] = server.command;
      if (command !== undefined) {
        vibeServer.command = command;
      }
      const args = [...commandArgs, ...(server.args ?? [])];
      if (args.length > 0) {
        vibeServer.args = args;
      }
    } else {
      vibeServer.command = server.command;
      if (server.args !== undefined) {
        vibeServer.args = server.args;
      }
    }
  }

  const hasStructuredAuth = serverRecord.auth !== undefined;
  for (const field of VIBE_MCP_SERVER_FIELDS) {
    if (field === "transport" || field === "command" || field === "args") {
      continue;
    }
    // Never emit legacy top-level static-auth keys alongside an `[auth]` block;
    // upstream rejects the mix.
    if (
      hasStructuredAuth &&
      (VIBE_LEGACY_STATIC_AUTH_FIELDS as readonly string[]).includes(field)
    ) {
      continue;
    }
    if (serverRecord[field] !== undefined) {
      vibeServer[field] = serverRecord[field];
    }
  }
  if (vibeServer.url === undefined && server.httpUrl !== undefined) {
    vibeServer.url = server.httpUrl;
  }
  // Canonical `disabledTools` is Vibe's `disabled_tools` (same semantics: hide
  // the named tools of this server), mirroring how `codexcli` renames it.
  if (server.disabledTools !== undefined) {
    vibeServer.disabled_tools = server.disabledTools;
  }

  return seedVibeUserManagedFields(vibeServer, existing);
}

/**
 * Carry over what the user set through Vibe's `/mcp` panel, unless the rulesync
 * source states it: `mcp_servers` is rewritten as a whole array, so anything not
 * re-stated here is lost.
 */
function seedVibeUserManagedFields(
  vibeServer: VibeMcpServer,
  existing: VibeMcpServer | undefined,
): VibeMcpServer {
  if (!existing) {
    return vibeServer;
  }
  for (const field of VIBE_MCP_USER_MANAGED_FIELDS) {
    if (vibeServer[field] === undefined && existing[field] !== undefined) {
      vibeServer[field] = existing[field];
    }
  }
  return vibeServer;
}

function vibeMcpServerToRulesync(server: VibeMcpServer): McpServer {
  const result: Record<string, unknown> = {};
  if (server.disabled_tools !== undefined) {
    result.disabledTools = server.disabled_tools;
  }
  const transport = typeof server.transport === "string" ? server.transport : undefined;
  if (transport !== undefined) {
    result.transport = transport;
    result.type = transport === "streamable-http" ? "streamable-http" : transport;
  }

  for (const field of VIBE_MCP_SERVER_FIELDS) {
    if (field === "transport") {
      continue;
    }
    if (server[field] !== undefined) {
      result[field] = server[field];
    }
  }

  return result as McpServer;
}

function resolveVibeTransport(server: McpServer): string | undefined {
  if (server.transport) {
    if (server.transport === "sse") {
      return "http";
    }
    if (server.transport === "local") {
      return "stdio";
    }
    return server.transport;
  }
  if (server.type) {
    if (server.type === "sse") {
      return "http";
    }
    if (server.type === "local") {
      return "stdio";
    }
    return server.type;
  }
  if (server.command) {
    return "stdio";
  }
  if (server.url || server.httpUrl) {
    return "http";
  }
  return undefined;
}
