import { join } from "node:path";

import { z } from "zod/mini";

import { SKILL_FILE_NAME } from "../../constants/general.js";
import { REPLIT_SKILLS_DIR_PATH } from "../../constants/replit-paths.js";
import { RULESYNC_SKILLS_RELATIVE_DIR_PATH } from "../../constants/rulesync-paths.js";
import { ValidationResult } from "../../types/ai-dir.js";
import { formatError } from "../../utils/error.js";
import { RulesyncSkill, RulesyncSkillFrontmatterInput, SkillFile } from "./rulesync-skill.js";
import { resolveCompatibility, resolveLicense, resolveMetadata } from "./skills-utils.js";
import {
  ToolSkill,
  ToolSkillForDeletionParams,
  ToolSkillFromDirParams,
  ToolSkillFromRulesyncSkillParams,
  ToolSkillSettablePaths,
} from "./tool-skill.js";

const ReplitSkillFrontmatterSchema = z.looseObject({
  name: z.string(),
  description: z.string(),
  // The Agent Skills spec, which Replit's skills page states conformance to,
  // types this as a space-separated string. The array form stays accepted so
  // existing rulesync inputs keep working. https://agentskills.io/specification
  "allowed-tools": z.optional(z.union([z.string(), z.array(z.string())])),
  license: z.optional(z.string()),
  // The spec types this as a 1-500 character string; the object form stays
  // accepted for back-compat.
  compatibility: z.optional(z.union([z.string(), z.looseObject({})])),
  metadata: z.optional(z.looseObject({})),
});

export type ReplitSkillFrontmatter = z.infer<typeof ReplitSkillFrontmatterSchema>;

export type ReplitSkillParams = {
  outputRoot?: string;
  relativeDirPath?: string;
  dirName: string;
  frontmatter: ReplitSkillFrontmatter;
  body: string;
  otherFiles?: SkillFile[];
  validate?: boolean;
  global?: boolean;
};

/**
 * Represents a Replit Agent skill directory.
 * Skills are stored under the .agents/skills directory with SKILL.md files.
 * Follows the open Agent Skills standard with name and description frontmatter.
 */
export class ReplitSkill extends ToolSkill {
  constructor({
    outputRoot = process.cwd(),
    relativeDirPath = REPLIT_SKILLS_DIR_PATH,
    dirName,
    frontmatter,
    body,
    otherFiles = [],
    validate = true,
    global = false,
  }: ReplitSkillParams) {
    super({
      outputRoot,
      relativeDirPath,
      dirName,
      mainFile: {
        name: SKILL_FILE_NAME,
        body,
        frontmatter: { ...frontmatter },
      },
      otherFiles,
      global,
    });

    if (validate) {
      const result = this.validate();
      if (!result.success) {
        throw result.error;
      }
    }
  }

  static getSettablePaths(_options?: { global?: boolean }): ToolSkillSettablePaths {
    // Replit Agent Skills document a user-level (personal) scope in addition to
    // the project scope, and follow the open Agent Skills standard, which defines
    // `.agents/skills/` (project) and `~/.agents/skills/` (personal/global). The
    // relative path is the same; the resolution root (cwd vs. home) is supplied
    // via outputRoot by the processor.
    // https://docs.replit.com/features/agent/skills (user-level scope)
    // https://agentskills.io/specification (`~/.agents/skills/` personal path)
    return {
      relativeDirPath: REPLIT_SKILLS_DIR_PATH,
    };
  }

  getFrontmatter(): ReplitSkillFrontmatter {
    const result = ReplitSkillFrontmatterSchema.parse(this.requireMainFileFrontmatter());
    return result;
  }

  getBody(): string {
    return this.mainFile?.body ?? "";
  }

  validate(): ValidationResult {
    if (!this.mainFile) {
      return {
        success: false,
        error: new Error(`${this.getDirPath()}: ${SKILL_FILE_NAME} file does not exist`),
      };
    }

    const result = ReplitSkillFrontmatterSchema.safeParse(this.mainFile.frontmatter);
    if (!result.success) {
      return {
        success: false,
        error: new Error(
          `Invalid frontmatter in ${this.getDirPath()}: ${formatError(result.error)}`,
        ),
      };
    }

    return { success: true, error: null };
  }

  toRulesyncSkill(): RulesyncSkill {
    const frontmatter = this.getFrontmatter();
    // Normalize back to the canonical rulesync array, mirroring
    // `DeepagentsSkill`, so a generate → import round trip is stable.
    const allowedTools = frontmatter["allowed-tools"];
    const allowedToolsArray =
      allowedTools === undefined
        ? undefined
        : Array.isArray(allowedTools)
          ? allowedTools
          : allowedTools.split(/\s+/).filter((tool) => tool.length > 0);
    const replitBlock = {
      ...(allowedToolsArray !== undefined &&
        allowedToolsArray.length > 0 && { "allowed-tools": allowedToolsArray }),
      ...(frontmatter.license !== undefined && { license: frontmatter.license }),
      ...(frontmatter.compatibility !== undefined && {
        compatibility: frontmatter.compatibility,
      }),
      ...(frontmatter.metadata !== undefined && { metadata: frontmatter.metadata }),
    };
    const rulesyncFrontmatter: RulesyncSkillFrontmatterInput = {
      name: frontmatter.name,
      description: frontmatter.description,
      targets: ["*"],
      ...(Object.keys(replitBlock).length > 0 && { replit: replitBlock }),
    };

    return new RulesyncSkill({
      outputRoot: this.outputRoot,
      relativeDirPath: RULESYNC_SKILLS_RELATIVE_DIR_PATH,
      dirName: this.getDirName(),
      frontmatter: rulesyncFrontmatter,
      body: this.getBody(),
      otherFiles: this.getOtherFiles(),
      validate: true,
      global: this.global,
    });
  }

  static fromRulesyncSkill({
    outputRoot = process.cwd(),
    rulesyncSkill,
    validate = true,
    global = false,
  }: ToolSkillFromRulesyncSkillParams): ReplitSkill {
    const settablePaths = ReplitSkill.getSettablePaths({ global });
    const rulesyncFrontmatter = rulesyncSkill.getFrontmatter();

    // Replit conforms to the Agent Skills spec, which types `allowed-tools` as a
    // space-separated string, so a canonical rulesync array is joined rather
    // than emitted as a YAML sequence. Mirrors `DeepagentsSkill`.
    const { "allowed-tools": allowedTools, ...replitSection } = rulesyncFrontmatter.replit ?? {};
    const allowedToolsString = Array.isArray(allowedTools) ? allowedTools.join(" ") : allowedTools;
    // The Agent Skills standard fields fall back to the root-level rulesync
    // value when the `replit` section omits them. Every resolver already prefers
    // a defined section value, so re-applying them after the spread never
    // discards one.
    const license = resolveLicense({
      rootFrontmatter: rulesyncFrontmatter,
      section: replitSection,
    });
    const compatibility = resolveCompatibility({
      rootFrontmatter: rulesyncFrontmatter,
      section: replitSection,
    });
    const metadata = resolveMetadata({
      rootFrontmatter: rulesyncFrontmatter,
      section: replitSection,
    });
    const replitFrontmatter: ReplitSkillFrontmatter = {
      name: rulesyncFrontmatter.name,
      description: rulesyncFrontmatter.description,
      ...(allowedToolsString && { "allowed-tools": allowedToolsString }),
      ...replitSection,
      ...(license !== undefined && { license }),
      ...(compatibility !== undefined && { compatibility }),
      ...(metadata !== undefined && { metadata }),
    };

    return new ReplitSkill({
      outputRoot,
      relativeDirPath: settablePaths.relativeDirPath,
      dirName: rulesyncSkill.getDirName(),
      frontmatter: replitFrontmatter,
      body: rulesyncSkill.getBody(),
      otherFiles: rulesyncSkill.getOtherFiles(),
      validate,
      global,
    });
  }

  static isTargetedByRulesyncSkill(rulesyncSkill: RulesyncSkill): boolean {
    const targets = rulesyncSkill.getFrontmatter().targets;
    return targets.includes("*") || targets.includes("replit");
  }

  static async fromDir(params: ToolSkillFromDirParams): Promise<ReplitSkill> {
    const loaded = await this.loadSkillDirContent({
      ...params,
      getSettablePaths: ReplitSkill.getSettablePaths,
    });

    const result = ReplitSkillFrontmatterSchema.safeParse(loaded.frontmatter);
    if (!result.success) {
      const skillDirPath = join(loaded.outputRoot, loaded.relativeDirPath, loaded.dirName);
      throw new Error(
        `Invalid frontmatter in ${join(skillDirPath, SKILL_FILE_NAME)}: ${formatError(result.error)}`,
      );
    }

    return new ReplitSkill({
      outputRoot: loaded.outputRoot,
      relativeDirPath: loaded.relativeDirPath,
      dirName: loaded.dirName,
      frontmatter: result.data,
      body: loaded.body,
      otherFiles: loaded.otherFiles,
      validate: true,
      global: loaded.global,
    });
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    dirName,
    global = false,
  }: ToolSkillForDeletionParams): ReplitSkill {
    const settablePaths = ReplitSkill.getSettablePaths({ global });
    return new ReplitSkill({
      outputRoot,
      relativeDirPath: relativeDirPath ?? settablePaths.relativeDirPath,
      dirName,
      frontmatter: { name: "", description: "" },
      body: "",
      otherFiles: [],
      validate: false,
      global,
    });
  }
}
