import { join } from "node:path";

import { z } from "zod/mini";

import { AGENTSMD_SKILLS_DIR_PATH } from "../../constants/agentsmd-paths.js";
import { SKILL_FILE_NAME } from "../../constants/general.js";
import { RULESYNC_SKILLS_RELATIVE_DIR_PATH } from "../../constants/rulesync-paths.js";
import { WARP_SKILLS_DIR_PATH } from "../../constants/warp-paths.js";
import { ValidationResult } from "../../types/ai-dir.js";
import { formatError } from "../../utils/error.js";
import { rulesyncCommandSlugExists } from "../commands/command-skill-ownership.js";
import { RulesyncSkill, RulesyncSkillFrontmatterInput, SkillFile } from "./rulesync-skill.js";
import {
  ToolSkill,
  ToolSkillForDeletionParams,
  ToolSkillFromDirParams,
  ToolSkillFromRulesyncSkillParams,
  ToolSkillSettablePaths,
} from "./tool-skill.js";

/**
 * Warp Agent Skills require at least `name` and `description` in the SKILL.md
 * frontmatter. Extra keys are tolerated (looseObject) because Warp's skill
 * schema may grow over time.
 */
export const WarpSkillFrontmatterSchema = z.looseObject({
  name: z.string(),
  description: z.string(),
});

export type WarpSkillFrontmatter = z.infer<typeof WarpSkillFrontmatterSchema>;

export type WarpSkillParams = {
  outputRoot?: string;
  relativeDirPath?: string;
  dirName: string;
  frontmatter: WarpSkillFrontmatter;
  body: string;
  otherFiles?: SkillFile[];
  validate?: boolean;
  global?: boolean;
};

/**
 * Represents a Warp Agent Skill directory.
 *
 * Each skill is a folder containing a `SKILL.md` (YAML frontmatter with the
 * required `name`/`description`, plus markdown instructions) and optional
 * supporting files. The layout mirrors the Claude Code / OpenCode skill
 * adapters.
 */
export class WarpSkill extends ToolSkill {
  constructor({
    outputRoot = process.cwd(),
    relativeDirPath = WARP_SKILLS_DIR_PATH,
    dirName,
    frontmatter,
    body,
    otherFiles = [],
    validate = true,
    global = false,
  }: WarpSkillParams) {
    super({
      outputRoot,
      relativeDirPath,
      dirName,
      mainFile: {
        name: SKILL_FILE_NAME,
        body,
        frontmatter: { ...frontmatter },
      },
      otherFiles,
      global,
    });

    if (validate) {
      const result = this.validate();
      if (!result.success) {
        throw result.error;
      }
    }
  }

  static getSettablePaths({
    global: _global = false,
  }: { global?: boolean } = {}): ToolSkillSettablePaths {
    // Warp reads project skills from `.warp/skills/` and user skills from
    // `~/.warp/skills/`; both share the relative path, with only the output
    // base differing. It also discovers the cross-tool Agent Skills root at
    // `<projectRoot>/.agents/skills/` and `~/.agents/skills/`, which Warp
    // documents as the recommended location. That root is import-only:
    // rulesync never writes there for this target, so a skill another tool put
    // in the shared tree must not become an orphan deletion candidate — least
    // of all under the user's home directory. When the same skill name exists
    // in both roots, the Warp-specific root wins.
    // @see https://docs.warp.dev/agents/capabilities/skills/
    return {
      relativeDirPath: WARP_SKILLS_DIR_PATH,
      importOnlySkillRoots: [AGENTSMD_SKILLS_DIR_PATH],
    };
  }

  getFrontmatter(): WarpSkillFrontmatter {
    const result = WarpSkillFrontmatterSchema.parse(this.requireMainFileFrontmatter());
    return result;
  }

  getBody(): string {
    return this.mainFile?.body ?? "";
  }

  validate(): ValidationResult {
    if (this.mainFile === undefined) {
      return {
        success: false,
        error: new Error(`${this.getDirPath()}: ${SKILL_FILE_NAME} file does not exist`),
      };
    }
    const result = WarpSkillFrontmatterSchema.safeParse(this.mainFile.frontmatter);
    if (!result.success) {
      return {
        success: false,
        error: new Error(
          `Invalid frontmatter in ${this.getDirPath()}: ${formatError(result.error)}`,
        ),
      };
    }

    return { success: true, error: null };
  }

  toRulesyncSkill(): RulesyncSkill {
    const frontmatter = this.getFrontmatter();
    const rulesyncFrontmatter: RulesyncSkillFrontmatterInput = {
      name: frontmatter.name,
      description: frontmatter.description,
      targets: ["*"],
    };

    return new RulesyncSkill({
      outputRoot: this.outputRoot,
      relativeDirPath: RULESYNC_SKILLS_RELATIVE_DIR_PATH,
      dirName: this.getDirName(),
      frontmatter: rulesyncFrontmatter,
      body: this.getBody(),
      otherFiles: this.getOtherFiles(),
      validate: true,
      global: this.global,
    });
  }

  static fromRulesyncSkill({
    outputRoot = process.cwd(),
    rulesyncSkill,
    validate = true,
    global = false,
  }: ToolSkillFromRulesyncSkillParams): WarpSkill {
    const rulesyncFrontmatter = rulesyncSkill.getFrontmatter();

    const warpFrontmatter: WarpSkillFrontmatter = {
      name: rulesyncFrontmatter.name,
      description: rulesyncFrontmatter.description,
    };

    const settablePaths = WarpSkill.getSettablePaths({ global });

    return new WarpSkill({
      outputRoot,
      relativeDirPath: settablePaths.relativeDirPath,
      dirName: rulesyncSkill.getDirName(),
      frontmatter: warpFrontmatter,
      body: rulesyncSkill.getBody(),
      otherFiles: rulesyncSkill.getOtherFiles(),
      validate,
      global,
    });
  }

  static isTargetedByRulesyncSkill(rulesyncSkill: RulesyncSkill): boolean {
    const targets = rulesyncSkill.getFrontmatter().targets;
    return targets.includes("*") || targets.includes("warp");
  }

  /**
   * Commands are emitted into the `.warp/skills/` tree as `<slug>/SKILL.md`
   * (see `WarpCommand`), so a directory there matching a current rulesync
   * command slug is owned by the commands feature: it must not be imported as
   * a skill nor deleted as an orphan skill. The import-only `.agents/skills/`
   * root never receives Warp commands, so a same-named skill in it stays a
   * skill (Antigravity commands emitted there are handled by the processor).
   */
  static async isDirOwned({
    relativeDirPath,
    dirName,
    inputRoots,
  }: {
    outputRoot: string;
    relativeDirPath: string;
    dirName: string;
    inputRoots: readonly string[];
  }): Promise<boolean> {
    if (relativeDirPath !== WARP_SKILLS_DIR_PATH) {
      return true;
    }
    return !(await rulesyncCommandSlugExists({ inputRoots, dirName }));
  }

  static async fromDir(params: ToolSkillFromDirParams): Promise<WarpSkill> {
    const loaded = await this.loadSkillDirContent({
      ...params,
      getSettablePaths: WarpSkill.getSettablePaths,
    });

    const result = WarpSkillFrontmatterSchema.safeParse(loaded.frontmatter);
    if (!result.success) {
      const skillDirPath = join(loaded.outputRoot, loaded.relativeDirPath, loaded.dirName);
      throw new Error(
        `Invalid frontmatter in ${join(skillDirPath, SKILL_FILE_NAME)}: ${formatError(result.error)}`,
      );
    }

    return new WarpSkill({
      outputRoot: loaded.outputRoot,
      relativeDirPath: loaded.relativeDirPath,
      dirName: loaded.dirName,
      frontmatter: result.data,
      body: loaded.body,
      otherFiles: loaded.otherFiles,
      validate: true,
      global: loaded.global,
    });
  }

  static forDeletion({
    outputRoot = process.cwd(),
    relativeDirPath,
    dirName,
    global = false,
  }: ToolSkillForDeletionParams): WarpSkill {
    return new WarpSkill({
      outputRoot,
      relativeDirPath,
      dirName,
      frontmatter: { name: "", description: "" },
      body: "",
      otherFiles: [],
      validate: false,
      global,
    });
  }
}
